INSERT INTO _n1_b6_guard_0121(ok) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM japanese_jlpt_daily_sessions s JOIN japanese_jlpt_study_plans p ON p.id=s.plan_id WHERE p.plan_code='N1_2027_JUL' AND s.study_date BETWEEN '2026-12-10' AND '2026-12-23' AND (s.status <> 'not_started' OR s.started_at IS NOT NULL OR s.completed_at IS NOT NULL)) THEN 1 ELSE 0 END;
INSERT INTO _n1_b6_words_0121(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-1694','2026-12-10','略語','りゃくご','약어; 준말','長い語・名称の一部を省略して短くした語。','専門用語の略語が多いため、資料の末尾に一覧を付けた。','전문 용어의 약어가 많아 자료 끝에 목록을 붙였다.'),
('n1-1711','2026-12-10','激励','げきれい','격려; 힘을 북돋움','勇気・意欲が出るよう強く励ますこと。','社長は現場を訪れ、復旧作業に当たる社員を激励した。','사장은 현장을 찾아 복구 작업 중인 직원들을 격려했다.'),
('n1-1886','2026-12-10','転任','てんにん','전임; 다른 근무지·직책으로 이동함','同じ組織内などで、勤務地や担当する職務を別の場所・職へ移すこと。','部長は四月付で大阪支社へ転任することになった。','부장은 4월부로 오사카 지사로 전임하게 되었다.'),
('n1-1926','2026-12-10','信任','しんにん','신임; 믿고 맡김','相手を信頼し、仕事・役割などを任せること。また、その信頼。','長年の実績が評価され、彼は取締役会から厚い信任を得ている。','오랜 실적을 인정받아 그는 이사회로부터 두터운 신임을 얻고 있다.'),
('n1-1985','2026-12-10','遭難','そうなん','조난; 재난을 당함','登山・航海などで災難に遭い、身動きが取れなくなること。','悪天候のため登山者が山中で遭難した。','악천후 때문에 등산객이 산에서 조난당했다.'),
('n1-2022','2026-12-10','軽減','けいげん','경감; 줄임; 완화','負担・苦痛・程度などを減らして軽くすること。','新しい制度によって利用者の負担が軽減された。','새 제도로 이용자의 부담이 줄었다.'),
('n1-2057','2026-12-10','危害','きがい','위해; 피해; 해를 끼침','人・物に危険や損害を与えること。また、その害。','他人に危害を加える行為は決して許されない。','타인에게 위해를 가하는 행위는 결코 용납되지 않는다.'),
('n1-1819','2026-12-10','乃至','ないし','~에서 ~까지; 또는; 내지','数量・範囲の両端を示して『〜から〜まで』の意を表す。また、選択肢を並べて『または』の意にも用いる。','参加者は三十人ないし四十人程度を見込んでいる。','참가자는 30명 내지 40명 정도로 예상하고 있다.'),
('n1-1761','2026-12-10','或いは','あるいは','혹은; 또는; 아니면','二つ以上の選択肢を示し、そのうちの一つを選ぶことを表す。','申請書は窓口、あるいはオンラインで提出することができる。','신청서는 창구 또는 온라인으로 제출할 수 있다.'),
('n1-1830','2026-12-10','若しくは','もしくは','혹은; 또는','二つ以上の選択肢のうち、いずれか一つを示す接続詞。','本人確認には運転免許証、もしくはパスポートを提示してください。','본인 확인에는 운전면허증 혹은 여권을 제시해 주세요.'),
('n1-2268','2026-12-10','碌な','ろくな','제대로 된; 변변한; 괜찮은','満足できる、まともな、十分な、という意味で、通常は否定表現を伴う。','忙しくて、今日はろくな食事をしていない。','바빠서 오늘은 변변한 식사를 하지 못했다.'),
('n1-2969','2026-12-10','重なる','おもなる','주된; 주요한; 중요한','中心となる。主要な。','会議では主なる課題について意見を交換した。','회의에서는 주요 과제에 대해 의견을 교환했다.'),
('n1-2081','2026-12-10','転居','てんきょ','전거; 이사; 거처를 옮김','住居を別の場所へ移すこと。','転居したので市役所で住所変更の手続きをした。','이사해서 시청에서 주소 변경 절차를 밟았다.'),
('n1-2113','2026-12-10','憤慨','ふんがい','분개; 몹시 화냄','不正・理不尽なことなどに激しく腹を立てること。','彼は会社の不公平な対応に憤慨した。','그는 회사의 불공정한 대응에 분개했다.'),
('n1-2157','2026-12-10','折衷','せっちゅう','절충; 절충안','異なる意見・方式などから良い部分を取り入れ、調和させること。','双方の案を折衷して新しい計画を作った。','양쪽 안을 절충해 새로운 계획을 만들었다.'),
('n1-2171','2026-12-10','嗜好','しこう','기호; 취향; 선호','飲食物・趣味などについての好み。','消費者の嗜好は時代とともに変化する。','소비자의 취향은 시대와 함께 변한다.'),
('n1-2208','2026-12-10','密集','みっしゅう','밀집; 빽빽하게 모임','多くのものが狭い場所にすき間なく集まること。','この地域には住宅が密集している。','이 지역에는 주택이 밀집해 있다.'),
('n1-2258','2026-12-10','老衰','ろうすい','노쇠; 노화로 쇠약해짐','年を取ることで心身の機能や体力が衰えること。','祖父は高齢になり、少しずつ老衰が進んでいる。','할아버지는 고령이 되어 조금씩 노쇠가 진행되고 있다.'),
('n1-2299','2026-12-10','類推','るいすい','유추; 비슷한 사례로 미루어 짐작함','似た性質・事例をもとに、別の事柄について推測すること。','過去の事例から類推すると、今回も同じ原因の可能性が高い。','과거 사례에서 유추하면 이번에도 같은 원인일 가능성이 높다.'),
('n1-2360','2026-12-10','倍率','ばいりつ','배율; 경쟁률','元の大きさに対する拡大・縮小の比率。また、募集人数に対する応募人数の割合。','この双眼鏡は十倍の倍率で見ることができる。','이 쌍안경은 10배 배율로 볼 수 있다.'),
('n1-2499','2026-12-11','慣例','かんれい','관례; 관행','長い間繰り返され、決まりのようになっているやり方・習慣。','この式典では代表者が最初に挨拶するのが慣例だ。','이 행사에서는 대표자가 먼저 인사하는 것이 관례다.'),
('n1-2583','2026-12-11','配偶者','はいぐうしゃ','배우자; 남편 또는 아내','夫婦の一方から見た、もう一方の人。','申請書には配偶者の有無を記入する欄がある。','신청서에는 배우자 유무를 기입하는 칸이 있다.'),
('n1-2591','2026-12-11','紡績','ぼうせき','방적; 실을 뽑음','綿・羊毛などの繊維から糸を作ること。','この地域では昔から紡績業が盛んだった。','이 지역에서는 예전부터 방적업이 활발했다.'),
('n1-2696','2026-12-11','屈折','くっせつ','굴절; 휘어짐; 비뚤어진 심리','折れ曲がること。光などが進行方向を変えること。また、心理が素直でないこと。','光は水に入るときに屈折する。','빛은 물에 들어갈 때 굴절한다.'),
('n1-2791','2026-12-11','化繊','かせん','화학섬유; 합성섬유','化学的に作られた繊維の総称。','この服は化繊なので乾きやすい。','이 옷은 화학섬유라서 잘 마른다.'),
('n1-2817','2026-12-11','優越','ゆうえつ','우월; 우위','他より優れていること。','技術面での優越を維持するには継続的な投資が必要だ。','기술 면에서의 우위를 유지하려면 지속적인 투자가 필요하다.'),
('n1-2825','2026-12-11','自転','じてん','자전','天体などが自身の軸を中心に回転すること。','地球は約二十四時間で一回自転する。','지구는 약 24시간에 한 번 자전한다.'),
('n1-2986','2026-12-11','転校','てんこう','전학','在籍している学校から別の学校へ移ること。','父の転勤で来月転校することになった。','아버지의 전근 때문에 다음 달 전학하게 되었다.'),
('n1-2993','2026-12-11','慣用','かんよう','관용; 관습적으로 사용함','長い間、習慣として広く使われていること。','この表現は慣用的に使われている。','이 표현은 관용적으로 사용되고 있다.'),
('n1-0018','2026-12-11','政策','せいさく','정책','政府や組織が目的を実現するために定める方針や手段。','政府は少子化対策として新たな支援政策を発表した。','정부는 저출산 대책으로 새로운 지원 정책을 발표했다。'),
('n1-0031','2026-12-11','理論','りろん','이론','事実や現象を筋道立てて説明するために体系化された考え。','この理論は実験結果とも一致しており、多くの研究者に支持されている。','이 이론은 실험 결과와도 일치하여 많은 연구자의 지지를 받고 있다。'),
('n1-0045','2026-12-11','危機','きき','위기','悪い結果につながる可能性が高く、重大な対応を迫られる危険な局面。','会社は経営危機を乗り越えるため、不採算事業の見直しに着手した。','회사는 경영 위기를 극복하기 위해 적자 사업 재검토에 착수했다。'),
('n1-0051','2026-12-11','政権','せいけん','정권','国家の政治を実際に行う権力、またはそれを担う政府。','新政権は発足直後から物価対策を最優先課題として掲げた。','새 정권은 출범 직후부터 물가 대책을 최우선 과제로 내세웠다。'),
('n1-0054','2026-12-11','権力','けんりょく','권력','他人や社会を従わせたり動かしたりできる政治的・社会的な力。','権力が一部の人に集中しすぎないよう、制度上の監視が必要だ。','권력이 일부 사람에게 지나치게 집중되지 않도록 제도적인 감시가 필요하다。'),
('n1-0123','2026-12-11','業務','ぎょうむ','업무','職場や組織で担当して行う仕事。','新しいシステムの導入によって、定型的な業務にかかる時間が大幅に減った。','새 시스템 도입으로 정형적인 업무에 걸리는 시간이 크게 줄었다.'),
('n1-0129','2026-12-11','自信','じしん','자신감; 확신','自分の能力や判断、物事の結果などを確かだと信じる気持ち。','何度も練習を重ねたことで、本番でも落ち着いて話せる自信がついた。','여러 번 연습을 거듭하면서 실전에서도 침착하게 말할 수 있다는 자신감이 생겼다.'),
('n1-0151','2026-12-11','任務','にんむ','임무','責任を持って果たすよう任せられた仕事や役目。','調査チームは原因を特定し、再発防止策をまとめる任務を担っている。','조사팀은 원인을 특정하고 재발 방지책을 정리하는 임무를 맡고 있다.'),
('n1-0359','2026-12-11','制服','せいふく','제복; 교복; 유니폼','学校・会社・団体などで、所属する人が規定に従って共通して着る服。','新しい制服は動きやすさを重視し、現場の意見を取り入れて設計された。','새 제복은 활동성을 중시해 현장 의견을 반영하여 설계되었다.'),
('n1-1690','2026-12-11','全快','ぜんかい','완쾌','病気・けがが完全に治ること。','医師から全快したと言われ、来週から仕事に復帰する。','의사에게 완쾌됐다는 말을 듣고 다음 주부터 업무에 복귀한다.'),
('n1-1697','2026-12-11','徐行','じょこう','서행','車両などがすぐ停止できる程度の低い速度でゆっくり進むこと。','工事区間では安全のため徐行してください。','공사 구간에서는 안전을 위해 서행해 주세요.');
INSERT INTO _n1_b6_words_0121(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-1705','2026-12-12','近眼','きんがん','근시; 근시안적임','近くは見えるが遠くが見えにくい目。また比喩的に、先のことを見通せない考え方。','短期の利益だけを追う近眼的な判断では将来の成長を損なう。','단기 이익만 좇는 근시안적 판단으로는 장래의 성장을 해친다.'),
('n1-2911','2026-12-12','聴覚','ちょうかく','청각; 듣는 감각','音を感じ取り、聞き分ける感覚。','大きな音を長時間聞き続けると、聴覚に負担がかかる。','큰 소리를 오랫동안 계속 들으면 청각에 부담이 간다.'),
('n1-1876','2026-12-12','先代','せんだい','선대; 전임자; 이전 세대의 당주','現在の人の前にその地位・家・店などを受け継いでいた人、または前の世代。','この店の製法は先代から受け継いだものを基本にしている。','이 가게의 제조법은 선대에게서 이어받은 방식을 기본으로 하고 있다.'),
('n1-1884','2026-12-12','着色','ちゃくしょく','착색; 색을 입힘','染料・顔料などを使って物に色を付けること。','この製品には人工的な着色を行わず、素材本来の色を生かしている。','이 제품은 인공 착색을 하지 않고 소재 본래의 색을 살리고 있다.'),
('n1-2017','2026-12-12','没落','ぼつらく','몰락; 쇠퇴','栄えていた家・組織・勢力などが衰えて地位を失うこと。','その一族は戦後急速に没落した。','그 가문은 전후 급속히 몰락했다.'),
('n1-2037','2026-12-12','遠方','えんぽう','먼 곳; 원거리','距離が遠く離れた場所。','遠方から来た参加者のために宿泊先を用意した。','먼 곳에서 온 참가자를 위해 숙소를 준비했다.'),
('n1-2045','2026-12-12','農耕','のうこう','농경; 경작','田畑を耕して農作物を作ること。','この地域では古くから農耕が盛んだった。','이 지역에서는 예로부터 농경이 활발했다.'),
('n1-2055','2026-12-12','差異','さい','차이; 차이점','二つ以上のものの間にある違い。','二つの方式には性能面で大きな差異はない。','두 방식에는 성능 면에서 큰 차이가 없다.'),
('n1-2076','2026-12-12','回送','かいそう','회송; 빈 차량 이동; 전달','車両などを客を乗せず別の場所へ移動させること。また、送られてきたものを別へ送ること。','この電車は終点から車庫へ回送される。','이 전철은 종점에서 차량기지로 회송된다.'),
('n1-2079','2026-12-12','粉末','ふんまつ','분말; 가루','細かく砕かれて粉状になったもの。','薬を粉末にして水に溶かした。','약을 가루로 만들어 물에 녹였다.'),
('n1-2119','2026-12-12','郷里','きょうり','고향; 출신지','生まれ育った土地。故郷。','退職後は郷里に戻るつもりだ。','퇴직 후에는 고향으로 돌아갈 생각이다.'),
('n1-2129','2026-12-12','丘陵','きゅうりょう','구릉; 낮은 언덕 지대','低い山や丘が続いている地形。','丘陵地帯には畑が広がっている。','구릉 지대에는 밭이 펼쳐져 있다.'),
('n1-2132','2026-12-12','計器','けいき','계기; 측정기; 계측기','温度・圧力・速度などを測定して示す器具。','運転前にすべての計器を確認した。','운전 전에 모든 계기를 확인했다.'),
('n1-2138','2026-12-12','辛抱','しんぼう','인내; 참음; 견딤','苦しさ・つらさなどを我慢して耐えること。','もう少し辛抱すれば状況は良くなる。','조금만 더 참으면 상황이 좋아질 것이다.'),
('n1-2144','2026-12-12','祝賀','しゅくが','축하; 경축','めでたい出来事を喜び祝うこと。','創立百周年の祝賀行事が開かれた。','창립 100주년 축하 행사가 열렸다.'),
('n1-2163','2026-12-12','微量','びりょう','미량; 극소량','ごくわずかな量。','この食品には微量のアルコールが含まれている。','이 식품에는 미량의 알코올이 포함되어 있다.'),
('n1-2194','2026-12-12','進呈','しんてい','증정; 드림','人に物を贈ること。やや改まった表現。','応募者全員に記念品を進呈します。','응모자 전원에게 기념품을 증정합니다.'),
('n1-2197','2026-12-12','飽和','ほうわ','포화; 포화 상태','それ以上受け入れられないほど満ちた状態。','市場はすでに飽和状態に近い。','시장은 이미 포화 상태에 가깝다.'),
('n1-2200','2026-12-12','微塵','みじん','미진; 아주 작은 티끌; 조금도','非常に細かい粒・ちり。また、『微塵も～ない』で少しもないこと。','彼には後悔の気持ちは微塵もなかった。','그에게는 후회의 마음이 조금도 없었다.'),
('n1-2202','2026-12-12','勘弁','かんべん','용서; 봐줌; 사양함','過ちを許すこと。また、『勘弁して』で、もうやめてほしいという気持ちを表す。','今日は残業だけは勘弁してください。','오늘은 야근만은 제발 봐주세요.'),
('n1-2205','2026-12-13','保温','ほおん','보온','温度が下がらないよう、暖かさを保つこと。','この水筒は長時間保温できる。','이 물통은 오랫동안 보온할 수 있다.'),
('n1-2225','2026-12-13','破裂','はれつ','파열; 터짐','内側から強い力がかかって裂けたり破れたりすること。','古いホースが水圧で破裂した。','낡은 호스가 수압으로 파열됐다.'),
('n1-2227','2026-12-13','盲点','もうてん','맹점; 미처 보지 못한 허점','注意が及ばず、見落としている点。','この計画には意外な盲点があった。','이 계획에는 뜻밖의 맹점이 있었다.'),
('n1-2241','2026-12-13','月賦','げっぷ','월부; 월부금; 월 할부','代金・借金などを毎月分けて支払うこと。また、その支払額。','家具を月賦で購入した。','가구를 월부로 구입했다.'),
('n1-2245','2026-12-13','大筋','おおすじ','대강; 큰 줄거리; 개요','細部を除いた、物事の大まかな内容・流れ。','計画の大筋については全員が合意した。','계획의 큰 틀에 대해서는 모두가 합의했다.'),
('n1-2250','2026-12-13','減点','げんてん','감점; 감점 점수','誤り・反則などを理由に点数を減らすこと。また、その点数。','記入漏れがあると減点される場合がある。','기입 누락이 있으면 감점될 수 있다.'),
('n1-2257','2026-12-13','目眩','めまい','현기증; 어지럼증','自分や周囲が回るように感じ、ふらつく症状。','急に立ち上がったら目眩がした。','갑자기 일어섰더니 현기증이 났다.'),
('n1-2261','2026-12-13','起伏','きふく','기복; 높낮이; 변화의 굴곡','土地などに高低があること。また、物事の変化に上がり下がりがあること。','このコースは起伏が激しく、初心者には少しきつい。','이 코스는 기복이 심해서 초보자에게는 조금 힘들다.'),
('n1-2340','2026-12-13','窒息','ちっそく','질식','気道がふさがる、酸素が不足するなどして呼吸できなくなること。','煙を大量に吸い込むと窒息する危険がある。','연기를 대량으로 들이마시면 질식할 위험이 있다.'),
('n1-2353','2026-12-13','放射能','ほうしゃのう','방사능','放射性物質が放射線を出す性質・能力。','事故後、周辺地域の放射能が継続的に測定された。','사고 후 주변 지역의 방사능이 지속적으로 측정됐다.'),
('n1-2361','2026-12-13','印鑑','いんかん','도장; 인감도장','名前などを彫り、書類などに印を押すための道具。印章。','契約書に署名し、印鑑を押した。','계약서에 서명하고 도장을 찍었다.'),
('n1-2367','2026-12-13','溶液','ようえき','용액','ある物質が別の物質に均一に溶けた液体。','塩を水に溶かして濃い溶液を作った。','소금을 물에 녹여 진한 용액을 만들었다.'),
('n1-2372','2026-12-13','拝借','はいしゃく','빌림; 빌리다의 겸양 표현','借りることをへりくだっていう語。','少しの間、ペンを拝借してもよろしいでしょうか。','잠시 펜을 빌려도 괜찮을까요?'),
('n1-2374','2026-12-13','弁償','べんしょう','변상; 배상','他人に与えた損害を金銭や代替物などで補うこと。','借りた物を壊したので、新しい物を買って弁償した。','빌린 물건을 망가뜨려 새 물건을 사서 변상했다.'),
('n1-2384','2026-12-13','辻褄','つじつま','앞뒤; 논리적 일관성; 말이 맞아떨어짐','話・説明などの筋道が通り、前後が一致すること。','彼の説明は辻褄が合っていない。','그의 설명은 앞뒤가 맞지 않는다.'),
('n1-2397','2026-12-13','原書','げんしょ','원서; 번역되지 않은 원본 책','翻訳・写本などのもとになった元の書物。','翻訳版ではなく原書で読んでみたい。','번역판이 아니라 원서로 읽어 보고 싶다.'),
('n1-2407','2026-12-13','郷愁','きょうしゅう','향수; 고향을 그리워하는 마음','故郷・昔の生活などを懐かしく思う気持ち。','故郷の写真を見ると強い郷愁を感じる。','고향 사진을 보면 강한 향수를 느낀다.'),
('n1-2507','2026-12-13','予言','かねごと','예언; 미리 한 말','将来起こることを前もって言うこと。また、その言葉。','物語では古い予言が後に現実となる。','이야기에서는 오래된 예언이 나중에 현실이 된다.'),
('n1-2525','2026-12-13','専修','せんしゅう','전수; 한 분야를 전문적으로 공부함; 전공','特定の分野・学問を専門に選び、集中的に学ぶこと。','大学では日本語教育を専修した。','대학에서는 일본어 교육을 전공했다.'),
('n1-2545','2026-12-13','粗筋','あらすじ','줄거리; 개요','物語・文章などの大まかな内容や展開。','映画を見る前に粗筋だけを読んだ。','영화를 보기 전에 줄거리만 읽었다.');
INSERT INTO _n1_b6_words_0121(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-2569','2026-12-14','敬具','けいぐ','경구; 삼가 올림(편지 맺음말)','改まった手紙の末尾に用いる結びの語。','正式な手紙の末尾を『敬具』で結んだ。','정식 편지의 마지막을 ''敬具''로 맺었다.'),
('n1-2570','2026-12-14','名残','なごり','흔적; 자취; 여운; 아쉬움','過ぎ去ったものが残した跡・気配。また、別れを惜しむ気持ち。','町には昔の面影の名残が残っている。','마을에는 옛 모습의 흔적이 남아 있다.'),
('n1-2606','2026-12-14','百科事典','ひゃっかじてん','백과사전','さまざまな分野の知識を体系的にまとめた事典。','分からない人物について百科事典で調べた。','모르는 인물에 대해 백과사전으로 찾아봤다.'),
('n1-2655','2026-12-14','遊牧','ゆうぼく','유목','家畜とともに牧草・水を求めて移動しながら生活すること。','この地域では昔から遊牧が行われてきた。','이 지역에서는 예전부터 유목이 이루어져 왔다.'),
('n1-2659','2026-12-14','文語','ぶんご','문어; 문어체','話し言葉に対し、文章で用いられる言葉や文体。','この表現は現代の会話ではなく文語で使われる。','이 표현은 현대 회화가 아니라 문어체에서 쓰인다.'),
('n1-2745','2026-12-14','域外','いきがい','지역 밖; 구역 밖','定められた区域・範囲の外。','この制度は域外の事業者には適用されない。','이 제도는 구역 밖 사업자에게는 적용되지 않는다.'),
('n1-2781','2026-12-14','蔵相','ぞうしょう','대장상; 옛 일본의 대장대신·재무상','旧称で、大蔵大臣のこと。現在の財務大臣に相当する。','古い新聞には蔵相という肩書が頻繁に登場する。','옛 신문에는 대장상이라는 직함이 자주 등장한다.'),
('n1-2782','2026-12-14','雅致','がち','아취; 우아한 멋; 품위 있는 정취','上品で風雅な趣。洗練された味わい。','この庭には落ち着いた雅致がある。','이 정원에는 차분하고 우아한 멋이 있다.'),
('n1-2784','2026-12-14','季刊','きかん','계간; 계간지','一年に四回、季節ごとに刊行すること。また、その刊行物。','この雑誌は季刊で発行されている。','이 잡지는 계간으로 발행된다.'),
('n1-2820','2026-12-14','特派','とくは','특파; 특별 파견','特別な任務のために人を派遣すること。','新聞社は記者を現地に特派した。','신문사는 기자를 현지에 특파했다.'),
('n1-2875','2026-12-14','光熱費','こうねつひ','광열비; 전기·가스 등 공공요금','電気・ガスなど、照明や冷暖房等にかかる費用。','冬は光熱費が高くなりやすい。','겨울에는 광열비가 높아지기 쉽다.'),
('n1-2974','2026-12-14','宣教','せんきょう','선교; 포교','宗教の教えを広く伝えて広めること。','彼は海外で宣教活動を行った。','그는 해외에서 선교 활동을 했다.'),
('n1-2977','2026-12-14','決行','けっこう','결행; 단행','決めた計画などを、覚悟をもって実行すること。','雨が降っても大会は予定通り決行する。','비가 와도 대회는 예정대로 강행한다.'),
('n1-2984','2026-12-14','気品','きひん','기품; 품격','人や物から感じられる上品で格調の高い雰囲気。','彼女の立ち居振る舞いには気品がある。','그녀의 몸가짐에는 기품이 있다.'),
('n1-2987','2026-12-14','幾多','いくた','수많은; 여러 많은','数が非常に多いこと。多くの。','幾多の困難を乗り越えて成功した。','수많은 어려움을 극복하고 성공했다.'),
('n1-2991','2026-12-14','蒸留','じょうりゅう','증류','液体を加熱して蒸気にし、それを冷却して再び液体として分離すること。','海水を蒸留して淡水を得る。','바닷물을 증류해 담수를 얻는다.'),
('n1-2994','2026-12-14','切開','せっかい','절개; 절개 수술','刃物などで切り開くこと。特に、手術で身体の一部を切り開くこと。','医師は患部を切開して処置した。','의사는 환부를 절개해 처치했다.'),
('n1-2998','2026-12-14','映写','えいしゃ','영사; 화면에 비춤','映画・スライドなどの像をスクリーンに映し出すこと。','古いフィルムをスクリーンに映写した。','오래된 필름을 스크린에 영사했다.'),
('n1-3000','2026-12-14','山腹','さんぷく','산허리; 산중턱','山頂と麓との間の斜面部分。','山腹に小さな村が見える。','산중턱에 작은 마을이 보인다.'),
('n1-0515','2026-12-14','敏感','びんかん','민감; 예민','小さな刺激・変化・問題などにもすぐ反応したり気付いたりすること。','金融市場は金利に関する発言に敏感に反応し、株価が大きく変動した。','금융시장은 금리에 관한 발언에 민감하게 반응해 주가가 크게 변동했다.'),
('n1-0003','2026-12-15','事業','じぎょう','사업','一定の目的のために継続して行う仕事や経営活動。','会社は海外事業を拡大するため、新しい拠点を設けた。','회사는 해외 사업을 확대하기 위해 새로운 거점을 마련했다。'),
('n1-0010','2026-12-15','発生','はっせい','발생','出来事や現象が起こること。また、新たに生じること。','システム障害が発生したため、一部のサービスを停止した。','시스템 장애가 발생하여 일부 서비스를 중단했다。'),
('n1-0017','2026-12-15','仕様','しよう','사양; 규격; 방식','製品やシステムなどに定められた構造・性能・処理方法。','顧客の要望に合わせて、システムの仕様を一部変更した。','고객의 요구에 맞추어 시스템 사양을 일부 변경했다。'),
('n1-0021','2026-12-15','交渉','こうしょう','교섭; 협상','利害や意見の異なる相手と話し合い、条件や結論を調整すること。','労使双方は賃金改定について交渉を続けている。','노사 양측은 임금 개정에 대해 협상을 계속하고 있다。'),
('n1-0029','2026-12-15','規模','きぼ','규모; 범위','物事の大きさや広がりの程度。','予想を上回る規模の災害となり、広い地域で停電が続いた。','예상을 웃도는 규모의 재해가 되어 넓은 지역에서 정전이 계속되었다。'),
('n1-0041','2026-12-15','指揮','しき','지휘','集団や組織の活動を統率し、目的に向けて動かすこと。','現場責任者が救助活動を指揮し、各班に具体的な役割を割り当てた。','현장 책임자가 구조 활동을 지휘하고 각 조에 구체적인 역할을 배정했다。'),
('n1-0043','2026-12-15','弁護','べんご','변호','人の立場や権利を守るため、その事情や正当性を説明してかばうこと。','弁護士は被告人を弁護するため、証拠と証言を一つずつ検討した。','변호사는 피고인을 변호하기 위해 증거와 증언을 하나씩 검토했다。'),
('n1-0044','2026-12-15','捜査','そうさ','수사','犯罪の事実や犯人を明らかにするため、警察や検察などが証拠を集めて調べること。','警察は防犯カメラの映像を分析しながら事件の捜査を進めている。','경찰은 방범카메라 영상을 분석하면서 사건 수사를 진행하고 있다。'),
('n1-0047','2026-12-15','改革','かいかく','개혁','制度や組織などの問題点を改め、よりよい状態へ大きく変えること。','行政改革を進めるには、手続きの簡素化だけでなく組織そのものの見直しも必要だ。','행정 개혁을 추진하려면 절차 간소화뿐 아니라 조직 자체의 재검토도 필요하다。'),
('n1-0055','2026-12-15','発言','はつげん','발언','会議や公の場などで、自分の意見や考えを言葉にして述べること。また、その内容。','彼の発言は誤解を招くとして、会議後も大きな議論になった。','그의 발언은 오해를 불러일으킨다는 이유로 회의 후에도 큰 논쟁이 되었다。'),
('n1-0072','2026-12-15','行政','ぎょうせい','행정','国や地方公共団体が法律に基づいて行う公的な事務や政策の執行。','人口減少に対応するには、複数の自治体が行政の枠を越えて協力する必要がある。','인구 감소에 대응하려면 여러 지자체가 행정의 틀을 넘어 협력할 필요가 있다。'),
('n1-0075','2026-12-15','廃止','はいし','폐지','それまで行われていた制度・規則・事業などをやめてなくすこと。','利用者の減少を理由に、その路線は来年度で廃止されることになった。','이용자 감소를 이유로 그 노선은 다음 연도에 폐지되기로 했다。'),
('n1-0079','2026-12-15','勢力','せいりょく','세력; 영향력','社会や集団の中で他に影響を及ぼす力。また、その力を持つ集団。','新しい政党が地方で勢力を伸ばし、選挙の行方が読みにくくなった。','새 정당이 지방에서 세력을 넓히면서 선거 결과를 예측하기 어려워졌다。'),
('n1-0087','2026-12-15','報道','ほうどう','보도','新聞・テレビ・インターネットなどを通じて、社会の出来事を広く伝えること。','事故の原因については情報が錯綜しており、報道各社も慎重に伝えている。','사고 원인에 대해서는 정보가 엇갈리고 있어 각 언론사도 신중하게 보도하고 있다.'),
('n1-0093','2026-12-15','株式','かぶしき','주식','株式会社における社員としての地位を細分化した単位。また、それを表す権利。','市場の動向を見ながら、保有する株式の一部を売却した。','시장 동향을 보면서 보유 주식의 일부를 매각했다.'),
('n1-0098','2026-12-15','協会','きょうかい','협회','共通の目的や事業のために、関係者が組織する団体。','業界の協会が新しいガイドラインを公表し、加盟企業に対応を求めた。','업계 협회가 새로운 가이드라인을 발표하고 회원 기업에 대응을 요구했다.'),
('n1-0099','2026-12-15','資格','しかく','자격; 자격 요건','ある立場・仕事・行為などに必要とされる条件や能力。また、それを満たしている身分。','この業務を担当するには、法律で定められた資格を取得している必要がある。','이 업무를 담당하려면 법률로 정해진 자격을 취득해야 한다.'),
('n1-0102','2026-12-15','業者','ぎょうしゃ','업자; 사업자; 업체','特定の事業を営む個人や会社。特に、仕事を請け負ったり商品・サービスを提供したりする者。','工事を依頼する前に、複数の業者から見積もりを取ることにした。','공사를 의뢰하기 전에 여러 업체에서 견적을 받기로 했다.'),
('n1-0104','2026-12-15','成果','せいか','성과; 결실','努力や活動の結果として得られた、価値のある結果。','研究の成果を社会に還元するため、企業との共同開発を始めた。','연구 성과를 사회에 환원하기 위해 기업과 공동 개발을 시작했다.'),
('n1-0116','2026-12-15','企画','きかく','기획; 기획안','目的を実現するため、事業・行事・製品などの内容や方法を計画すること。また、その計画。','若手社員が企画したイベントが予想以上の来場者を集めた。','젊은 직원이 기획한 행사가 예상보다 많은 방문객을 모았다.');
INSERT INTO _n1_b6_words_0121(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-0117','2026-12-16','作戦','さくせん','작전; 전략','目的を達成するために立てる具体的な方法や計画。軍事行動の計画にも用いる。','競合との差を明確にする作戦が功を奏し、新商品の売上が伸びた。','경쟁사와의 차이를 분명히 하는 전략이 효과를 내 신상품 매출이 늘었다.'),
('n1-0119','2026-12-16','防衛','ぼうえい','방위; 방어','外部からの攻撃や侵略を防ぎ、自国・組織・立場などを守ること。','政府は周辺情勢の変化を踏まえ、防衛体制の見直しを進めている。','정부는 주변 정세 변화를 고려해 방위 체계 재검토를 추진하고 있다.'),
('n1-0120','2026-12-16','運営','うんえい','운영; 경영','組織・施設・事業などが目的を達成できるよう、管理しながら動かしていくこと。','限られた予算で施設を安定して運営するには、業務の効率化が必要だ。','제한된 예산으로 시설을 안정적으로 운영하려면 업무 효율화가 필요하다.'),
('n1-0125','2026-12-16','革命','かくめい','혁명; 획기적 변화','政治・社会の制度や仕組みを根本から大きく変えること。また、比喩的に技術や方法の画期的な変化にもいう。','通信技術の発達は、人々の情報交換の方法に革命をもたらした。','통신기술의 발달은 사람들이 정보를 주고받는 방식에 혁명적인 변화를 가져왔다.'),
('n1-0127','2026-12-16','暴力','ぼうりょく','폭력','人を傷つけたり強制したりするために、身体的な力などを不当に用いること。','意見が対立しても、暴力によって相手を従わせることは許されない。','의견이 대립하더라도 폭력으로 상대를 굴복시키는 것은 용납될 수 없다.'),
('n1-0131','2026-12-16','内閣','ないかく','내각','内閣総理大臣と国務大臣によって構成され、国の行政を担う最高の合議機関。','新しい内閣は、経済対策を最優先課題として掲げた。','새 내각은 경제 대책을 최우선 과제로 내세웠다.'),
('n1-0184','2026-12-16','共和','きょうわ','공화; 공화정','君主ではなく国民またはその代表が政治に参加し、公共の意思に基づいて国を治める考え方や制度。','王政が廃止された後、その国は共和制へ移行した。','왕정이 폐지된 뒤 그 나라는 공화제로 이행했다.'),
('n1-0185','2026-12-16','興奮','こうふん','흥분','強い刺激を受けて、感情や神経の働きが高ぶること。','会場は試合終了直前の逆転劇に興奮し、大きな歓声に包まれた。','경기 종료 직전의 역전극에 관중이 흥분하며 경기장은 큰 환호로 가득 찼다.'),
('n1-0220','2026-12-16','工作','こうさく','공작; 제작; 계략','材料を加工して物を作ること。また、目的を達成するために裏で働きかけたり策をめぐらしたりすること。','世論を誘導するための情報工作が行われた可能性について調査が始まった。','여론을 유도하기 위한 정보 공작이 이루어졌을 가능성에 대해 조사가 시작되었다.'),
('n1-0230','2026-12-16','始末','しまつ','처리; 수습; 정리','問題や物事を最後まで処理して片づけること。また、事の成り行きや結果をいう場合もある。','自分で起こした問題なのだから、最後まで責任を持って始末するべきだ。','자신이 일으킨 문제이므로 끝까지 책임지고 처리해야 한다.'),
('n1-0242','2026-12-16','人民','じんみん','인민; 국민 대중','ある国家や社会を構成する一般の人々を集合的にいう語。','憲法は国家権力だけでなく、人民の権利をどのように守るかという観点からも論じられる。','헌법은 국가 권력뿐 아니라 인민의 권리를 어떻게 지킬 것인가라는 관점에서도 논의된다.'),
('n1-0243','2026-12-16','正義','せいぎ','정의; 올바름','社会的・道徳的に正しいと考えられる道理や原則。','自分の正義だけを絶対視すると、異なる立場の人との対話が難しくなる。','자신의 정의만을 절대시하면 다른 입장의 사람과 대화하기 어려워진다.'),
('n1-0245','2026-12-16','起源','きげん','기원; 유래','ある物事・制度・習慣・生物などが最初に生じたもとや始まり。','この祭りの起源については複数の説があり、正確なことは分かっていない。','이 축제의 기원에 대해서는 여러 설이 있어 정확한 사실은 알려져 있지 않다.'),
('n1-0280','2026-12-16','保守','ほしゅ','보수; 유지보수; 보수적 입장','既存の制度・伝統・価値を守ろうとすること。また、機械・設備・システムなどを正常に保つため点検・修理すること。','システムの安定運用には、開発だけでなく定期的な保守も欠かせない。','시스템을 안정적으로 운용하려면 개발뿐 아니라 정기적인 유지보수도 필수적이다.'),
('n1-0283','2026-12-16','補助','ほじょ','보조; 도움; 지원','中心となる働きや不足している部分を助け、補うこと。','高齢者の移動を補助するため、駅に新しい設備が設置された。','고령자의 이동을 보조하기 위해 역에 새로운 설비가 설치되었다.'),
('n1-0286','2026-12-16','衛生','えいせい','위생','病気を予防し健康を守るため、生活環境や食品などを清潔で安全な状態に保つこと。','食品を扱う職場では、衛生管理の手順を全員が守らなければならない。','식품을 취급하는 직장에서는 위생 관리 절차를 전원이 지켜야 한다.'),
('n1-0291','2026-12-16','工学','こうがく','공학','科学的知識を応用し、機械・電気・情報・土木などの技術を研究・設計する学問分野。','大学では情報工学を専攻し、ネットワークとソフトウェア設計を学んだ。','대학에서는 정보공학을 전공하여 네트워크와 소프트웨어 설계를 배웠다.'),
('n1-0300','2026-12-16','経費','けいひ','경비; 비용','事業・活動・仕事などを行うために必要となる費用。','出張にかかった交通費と宿泊費は、規定の範囲内で経費として精算できる。','출장에 든 교통비와 숙박비는 규정 범위 내에서 경비로 정산할 수 있다.'),
('n1-0302','2026-12-16','牧師','ぼくし','목사','主にプロテスタント教会で、礼拝を導き信者の信仰生活を支える聖職者。','地域の牧師は教会で礼拝を行うだけでなく、生活相談にも応じている。','지역 목사는 교회에서 예배를 진행할 뿐 아니라 생활 상담에도 응하고 있다.'),
('n1-0311','2026-12-16','助言','じょげん','조언; 충고','相手の判断や行動の助けになるよう、意見や考えを伝えること。また、その言葉。','専門家の助言を受けながら、契約条件に法的な問題がないか確認した。','전문가의 조언을 받으면서 계약 조건에 법적인 문제가 없는지 확인했다.'),
('n1-0312','2026-12-17','国連','こくれん','유엔; 국제연합','国際連合の略称。国際平和と安全の維持、国際協力などを目的とする国際機関。','国連は紛争地域への人道支援を拡大するよう各国に協力を求めた。','유엔은 분쟁 지역에 대한 인도적 지원을 확대하도록 각국에 협력을 요청했다.'),
('n1-0313','2026-12-17','名称','めいしょう','명칭; 이름','人・物・制度・組織などを他と区別して呼ぶための名前。','組織改編に伴って部署の名称は変わったが、担当業務はほぼ同じだ。','조직 개편에 따라 부서 명칭은 바뀌었지만 담당 업무는 거의 같다.'),
('n1-0317','2026-12-17','方式','ほうしき','방식; 형식','物事を行うために定められた一定の方法や仕組み。','従来の一括処理方式から、データを随時処理する方式へ変更した。','기존의 일괄 처리 방식에서 데이터를 수시로 처리하는 방식으로 변경했다.'),
('n1-0322','2026-12-17','騒動','そうどう','소동; 소란; 큰 파문','多くの人を巻き込み、社会や周囲が騒がしく混乱する出来事。','誤った情報がSNSで広がり、会社が公式に否定するほどの騒動になった。','잘못된 정보가 SNS에 퍼져 회사가 공식 부인할 정도의 소동이 되었다.'),
('n1-0323','2026-12-17','所得','しょとく','소득; 수입','個人や法人が労働・事業・資産などによって一定期間に得る収入や利益。','所得に応じて税負担が変わる制度について、見直しが議論されている。','소득에 따라 세 부담이 달라지는 제도에 대해 재검토가 논의되고 있다.'),
('n1-0327','2026-12-17','庶民','しょみん','서민; 일반 대중','特別な地位や権力を持たない、一般の人々。','この料理はもともと庶民の家庭料理として広まり、後に全国で知られるようになった。','이 요리는 원래 서민의 가정요리로 퍼졌다가 나중에 전국적으로 알려지게 되었다.'),
('n1-0330','2026-12-17','復興','ふっこう','부흥; 복구; 재건','災害・戦争・衰退などで弱った地域・産業・社会を、再び盛んな状態へ立て直すこと。','被災地の復興には、住宅の再建だけでなく雇用の確保も欠かせない。','재해 지역의 부흥에는 주택 재건뿐 아니라 고용 확보도 필수적이다.'),
('n1-0332','2026-12-17','新人','しんじん','신인; 신입; 새로 들어온 사람','ある組織・職業・分野に新しく入り、活動を始めた人。','新人が早く仕事に慣れるよう、先輩社員が一人ずつ指導を担当している。','신입이 빨리 업무에 익숙해지도록 선배 사원이 한 명씩 지도를 담당하고 있다.'),
('n1-0338','2026-12-17','委託','いたく','위탁; 맡김','業務・管理・処理などを、契約などに基づいて他の人や組織に任せること。','専門性の高い保守作業は、外部の会社に委託することになった。','전문성이 높은 유지보수 작업은 외부 회사에 위탁하기로 했다.'),
('n1-0339','2026-12-17','移住','いじゅう','이주; 이주하여 정착함','現在の居住地を離れ、別の地域や国へ移って生活の拠点を置くこと。','地方へ移住しても仕事を続けられるよう、遠隔勤務制度を利用する人が増えている。','지방으로 이주해도 일을 계속할 수 있도록 원격근무 제도를 이용하는 사람이 늘고 있다.'),
('n1-0340','2026-12-17','農場','のうじょう','농장','農作物の栽培や家畜の飼育など、農業を営むための土地・施設。','この農場では農薬の使用を抑え、環境に配慮した野菜を生産している。','이 농장에서는 농약 사용을 줄이고 환경을 고려한 채소를 생산하고 있다.'),
('n1-0341','2026-12-17','面会','めんかい','면회; 직접 만남','人と直接会うこと。特に病院・施設・拘置所など、出入りが制限された場所にいる人を訪ねて会うこと。','入院中の患者との面会は、感染対策のため一日一組に制限されている。','입원 환자와의 면회는 감염 대책 때문에 하루 한 팀으로 제한되어 있다.'),
('n1-0343','2026-12-17','出産','しゅっさん','출산; 분만','母体から子どもを産むこと。','出産後も安心して働き続けられるよう、育児支援制度を拡充する企業が増えている。','출산 후에도 안심하고 계속 일할 수 있도록 육아 지원 제도를 확대하는 기업이 늘고 있다.'),
('n1-0347','2026-12-17','取材','しゅざい','취재; 자료 조사','記事・番組・作品などを作るため、現場を訪ねたり関係者に話を聞いたりして材料を集めること。','記者は事故の原因を調べるため、現場と関係者の双方を取材した。','기자는 사고 원인을 조사하기 위해 현장과 관계자 양쪽을 취재했다.'),
('n1-0349','2026-12-17','所在','しょざい','소재; 있는 곳; 위치','人や物が存在している場所。また、責任・原因などがどこにあるかという所在。','紛失した書類の所在を確認しているが、まだ見つかっていない。','분실된 서류의 소재를 확인하고 있지만 아직 찾지 못했다.'),
('n1-0357','2026-12-17','声明','せいめい','성명; 공식 입장 발표','社会的に重要な問題について、個人・団体・政府などが立場や意見を公式に公表すること。また、その文書。','団体は報道内容に事実と異なる点があるとして、訂正を求める声明を発表した。','단체는 보도 내용에 사실과 다른 점이 있다며 정정을 요구하는 성명을 발표했다.'),
('n1-0358','2026-12-17','使命','しめい','사명; 맡겨진 중대한 임무','自分や組織が果たすべき重要な役割・任務。','医療機関には、緊急時にも地域住民の命を守るという使命がある。','의료기관에는 긴급 상황에서도 지역 주민의 생명을 지킨다는 사명이 있다.'),
('n1-0360','2026-12-17','従事','じゅうじ','종사; 업무에 종사함','ある仕事・職業・業務に継続して携わること。','彼は大学卒業後、二十年以上にわたって医療関係の仕事に従事してきた。','그는 대학 졸업 후 20년 넘게 의료 관련 업무에 종사해 왔다.'),
('n1-0368','2026-12-17','前提','ぜんてい','전제; 전제조건','議論・判断・計画などが成り立つために、あらかじめ正しいものとして置かれる条件や考え。','全員が同じ前提で話しているとは限らないので、最初に条件を確認しよう。','모두가 같은 전제를 두고 이야기한다고는 할 수 없으니 먼저 조건을 확인하자.'),
('n1-0369','2026-12-17','業績','ぎょうせき','업적; 실적; 경영 성과','仕事・事業・研究などで上げた成果や成績。企業では経営上の実績を指すことも多い。','海外事業が好調だったため、会社の今年度の業績は過去最高となった。','해외 사업이 호조를 보여 회사의 올해 실적은 역대 최고가 되었다.');
INSERT INTO _n1_b6_words_0121(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-0373','2026-12-18','存続','そんぞく','존속; 계속 존재함','組織・制度・状態などがなくならず、そのまま存在し続けること。','利用者が減り続ければ、この公共施設の存続自体が難しくなる。','이용자가 계속 줄어들면 이 공공시설의 존속 자체가 어려워진다.'),
('n1-0374','2026-12-18','投入','とうにゅう','투입; 투여; 쏟아부음','人員・資金・物資・労力などを必要な場所や目的に注ぎ込むこと。物を中へ入れる意味もある。','納期に間に合わせるため、追加の人員と予算をプロジェクトに投入した。','납기를 맞추기 위해 추가 인력과 예산을 프로젝트에 투입했다.'),
('n1-0375','2026-12-18','主体','しゅたい','주체; 중심이 되는 존재','行動・活動・判断などを自ら行う中心的な存在。また、物事の中心となる部分。','地域の活性化は行政だけでなく、住民自身が主体となって進めることが重要だ。','지역 활성화는 행정뿐 아니라 주민 스스로가 주체가 되어 추진하는 것이 중요하다.'),
('n1-0376','2026-12-18','融資','ゆうし','융자; 대출; 자금 대여','銀行などの金融機関が、企業や個人に資金を貸し出すこと。また、その資金。','創業資金を確保するため、銀行に融資を申し込んだ。','창업 자금을 확보하기 위해 은행에 융자를 신청했다.'),
('n1-0378','2026-12-18','経歴','けいれき','경력; 이력','これまでの学歴・職歴・活動歴など、その人が経験してきた事柄の記録。','応募書類には、これまでの職務経歴を新しい順に記載してください。','지원 서류에는 지금까지의 직무 경력을 최신 순서로 기재해 주세요.'),
('n1-0379','2026-12-18','審議','しんぎ','심의; 신중한 논의','議会・委員会などで、提案や議案の内容を詳しく検討し議論すること。','新しい法案は来週の委員会で本格的に審議される予定だ。','새 법안은 다음 주 위원회에서 본격적으로 심의될 예정이다.'),
('n1-0380','2026-12-18','移行','いこう','이행; 전환','ある制度・状態・システムなどから、別のものへ段階的に切り替わること。','旧システムから新システムへの移行は、三か月かけて段階的に行う。','기존 시스템에서 새 시스템으로의 이행은 3개월에 걸쳐 단계적으로 진행한다.'),
('n1-0382','2026-12-18','浮気','うわき','바람; 외도; 변덕스러움','配偶者・恋人以外の人と恋愛関係を持つこと。また、気持ちが一つのものに定まらず移りやすいこと。','長年の信頼関係があっても、浮気がきっかけで関係が壊れることはある。','오랜 신뢰 관계가 있어도 외도가 계기가 되어 관계가 깨질 수 있다.'),
('n1-0383','2026-12-18','共産','きょうさん','공산; 공동 소유; 공산주의 관련','財産や生産手段などを共同で所有・管理するという考え方。『共産主義』『共産党』などの複合語で多く用いられる。','二十世紀の国際政治を理解するには、共産主義と資本主義の対立を避けて通れない。','20세기 국제정치를 이해하려면 공산주의와 자본주의의 대립을 빼놓을 수 없다.'),
('n1-0388','2026-12-18','遺跡','いせき','유적; 유적지','昔の建物・住居・施設など、人間の活動の痕跡が残されている場所や遺構。','工事現場から古代の遺跡が発見され、計画はいったん中断された。','공사 현장에서 고대 유적이 발견되어 계획이 일단 중단되었다.'),
('n1-0392','2026-12-18','電源','でんげん','전원; 전력 공급원','機器に電気を供給する源。また、機器の電源を入れたり切ったりする機能を指すこともある。','作業を始める前に装置の電源を切り、感電しないことを確認してください。','작업을 시작하기 전에 장치의 전원을 끄고 감전 위험이 없는지 확인해 주세요.'),
('n1-0395','2026-12-18','会談','かいだん','회담; 회동','政治家・代表者などが会い、重要な問題について公式または準公式に話し合うこと。','両国首脳は二時間にわたって会談し、安全保障問題について意見を交換した。','양국 정상은 두 시간 동안 회담하며 안보 문제에 대해 의견을 교환했다.'),
('n1-0396','2026-12-18','国土','こくど','국토','一つの国家の主権が及ぶ土地・領域。','国土の多くが山地であるため、利用できる平地は限られている。','국토의 많은 부분이 산지이기 때문에 이용할 수 있는 평지는 한정되어 있다.'),
('n1-0398','2026-12-18','宮殿','きゅうでん','궁전','王・皇帝などの君主が住んだり、公的な儀式を行ったりする大規模な建物。','かつて王族が暮らした宮殿は、現在では博物館として一般公開されている。','과거 왕족이 살았던 궁전은 현재 박물관으로 일반 공개되고 있다.'),
('n1-0400','2026-12-18','戦術','せんじゅつ','전술; 구체적 전략 수단','戦闘で目的を達成するための具体的な方法。また、競争や交渉などで使う具体的な手段にもいう。','長期的な戦略と、目の前の課題に対応する戦術を混同してはいけない。','장기적인 전략과 눈앞의 과제에 대응하는 전술을 혼동해서는 안 된다.'),
('n1-0386','2026-12-18','過ち','あやまち','잘못; 과오; 실수','判断や行動を誤って起こした間違い・失敗。道徳的な誤りを指すこともある。','過去の過ちを認め、同じ失敗を繰り返さない仕組みを作ることが重要だ。','과거의 잘못을 인정하고 같은 실수를 반복하지 않는 구조를 만드는 것이 중요하다.'),
('n1-0428','2026-12-18','上陸','じょうりく','상륙; 육지에 오름','船などから陸地に上がること。また、台風などが海上から陸地へ入ることにもいう。','大型台風は夜遅く西日本に上陸する見込みで、各地に避難情報が出ている。','대형 태풍은 밤늦게 서일본에 상륙할 전망이라 각지에 대피 정보가 내려져 있다.'),
('n1-0429','2026-12-18','上演','じょうえん','상연; 무대에 올림','演劇・舞踊・音楽作品などを舞台で演じ、観客に見せること。','この作品は初演から百年を経た今も、世界各地の劇場で上演されている。','이 작품은 초연 후 100년이 지난 지금도 세계 각지의 극장에서 상연되고 있다.'),
('n1-0435','2026-12-18','信者','しんじゃ','신자; 신도','特定の宗教・教え・信仰を信じ、その信仰に従う人。','祭礼には地域の信者だけでなく、観光客も多数訪れた。','제례에는 지역 신자뿐 아니라 관광객도 많이 방문했다.'),
('n1-0444','2026-12-18','配慮','はいりょ','배려; 고려','相手や周囲の事情・影響などを考え、問題が起きないよう気を配ること。','高齢者や障害のある利用者にも使いやすいよう、画面設計に十分配慮した。','고령자나 장애가 있는 이용자도 사용하기 쉽도록 화면 설계에 충분히 배려했다.'),
('n1-0537','2026-12-19','逆転','ぎゃくてん','역전; 형세가 뒤바뀜','順位・勝敗・状況などがそれまでと反対の状態に変わること。また、反対に変えること。','終了間際の得点でチームは逆転に成功し、そのまま勝利した。','종료 직전의 득점으로 팀은 역전에 성공해 그대로 승리했다.'),
('n1-0570','2026-12-19','上空','じょうくう','상공; 어떤 지역의 위쪽 하늘','ある地点・地域の上に広がる空中。','台風の影響で空港上空の風が強まり、多くの便が欠航した。','태풍의 영향으로 공항 상공의 바람이 강해져 많은 항공편이 결항되었다.'),
('n1-0613','2026-12-19','予感','よかん','예감; 일이 일어날 것 같은 느낌','まだ起きていない出来事について、そうなりそうだと前もって感じること。','企画書を読んだ瞬間、この案は成功するという予感がした。','기획서를 읽는 순간 이 안은 성공할 것 같은 예감이 들었다.'),
('n1-0641','2026-12-19','直感','ちょっかん','직감; 직관적으로 느낌','考えを段階的に進める前に、感覚的・瞬間的に本質や答えをとらえること。','最初の違和感を直感だけで片づけず、データを確認して原因を探った。','처음 느낀 위화감을 직감만으로 넘기지 않고 데이터를 확인해 원인을 찾았다.'),
('n1-0458','2026-12-19','神聖','しんせい','신성; 성스러움','宗教的・精神的に非常に尊く、汚したり軽んじたりしてはならないとされること。','その山は地域の人々にとって神聖な場所として長く守られてきた。','그 산은 지역 사람들에게 신성한 장소로 오랫동안 지켜져 왔다.'),
('n1-0473','2026-12-19','空腹','くうふく','공복; 배고픔; 빈속','食事を取っておらず、胃が空いて腹が減っている状態。','空腹のまま長時間運動すると体調を崩すことがあるので注意が必要だ。','공복 상태로 장시간 운동하면 몸 상태가 나빠질 수 있으므로 주의가 필요하다.'),
('n1-0483','2026-12-19','依然','いぜん','여전히; 여전하게','以前と変わらない状態がそのまま続いているさま。多く『依然として』の形で用いる。','対策を進めているものの、人手不足は依然として深刻な状況だ。','대책을 추진하고 있지만 인력 부족은 여전히 심각한 상황이다.'),
('n1-0502','2026-12-19','特有','とくゆう','특유; 고유한 특성','ある人・地域・物などだけに特に見られる性質・特徴を持つこと。','この地域特有の気候が、独特な農産物の生産を可能にしている。','이 지역 특유의 기후가 독특한 농산물 생산을 가능하게 하고 있다.'),
('n1-0508','2026-12-19','相応','そうおう','상응; 걸맞음; 알맞음','地位・能力・状況・価値などに釣り合っていて、ふさわしいこと。','責任の大きさに相応した権限を与えなければ、仕事を任せたことにはならない。','책임의 크기에 상응하는 권한을 주지 않으면 일을 맡긴 것이 아니다.'),
('n1-0536','2026-12-19','早急','さっきゅう','조속; 시급; 서둘러야 함','非常に急いで対応する必要があること。『そうきゅう』とも読む。','安全上の問題が確認されたため、早急に原因を調査して対策を取らなければならない。','안전상의 문제가 확인되어 조속히 원인을 조사하고 대책을 마련해야 한다.'),
('n1-0540','2026-12-19','無知','むち','무지; 알지 못함','必要な知識がなく、物事を知らないこと。','自分の無知を認めて質問することは、決して恥ずかしいことではない。','자신의 무지를 인정하고 질문하는 것은 결코 부끄러운 일이 아니다.'),
('n1-0587','2026-12-19','身近','みぢか','가까움; 친숙함; 생활 주변에 있음','自分のすぐ近くにあること。また、日常的に接していて親しみやすいこと。','環境問題を身近な問題として考えることが、行動を変える第一歩になる。','환경 문제를 가까운 문제로 생각하는 것이 행동을 바꾸는 첫걸음이 된다.'),
('n1-0597','2026-12-19','固有','こゆう','고유; 그 대상만이 본래 지닌 것','ある人・地域・物・種類などだけが本来もっている、そのもの特有の性質。','この地域には、長い歴史の中で形成された固有の文化が残っている。','이 지역에는 오랜 역사 속에서 형성된 고유한 문화가 남아 있다.'),
('n1-0601','2026-12-19','日頃','ひごろ','평소; 평상시; 늘','特別な時ではない普段の日常。また、普段からという意味でも使う。','災害に備えるには、日頃から家族で避難場所を確認しておくことが大切だ。','재해에 대비하려면 평소부터 가족끼리 대피 장소를 확인해 두는 것이 중요하다.'),
('n1-0603','2026-12-19','好調','こうちょう','호조; 상태·성과가 좋음','物事の進み具合・成績・売上・体調などが順調で、よい状態にあるさま。','新商品の売れ行きが好調で、会社は年間予想を上方修正した。','신상품 판매가 호조여서 회사는 연간 전망을 상향 조정했다.'),
('n1-0616','2026-12-19','優位','ゆうい','우위; 다른 것보다 유리하고 앞선 위치','比較した相手よりも有利で、能力・地位・条件などが上にあること。','技術力だけで優位を保つのは難しく、サービス面での差別化も必要だ。','기술력만으로 우위를 유지하기는 어려워 서비스 측면의 차별화도 필요하다.'),
('n1-0631','2026-12-19','時折','ときおり','때때로; 이따금','頻繁ではないが、時々。','普段は静かな地域だが、冬になると時折強い風が吹く。','평소에는 조용한 지역이지만 겨울이 되면 이따금 강한 바람이 분다.'),
('n1-0676','2026-12-19','無茶','むちゃ','무리함; 터무니없음; 난폭함','道理に合わず、程度を超えて無理・乱暴であるさま。','納期を半分にするという無茶な要求には、根拠を示して断るべきだ。','납기를 절반으로 줄이라는 무리한 요구에는 근거를 제시해 거절해야 한다.'),
('n1-0680','2026-12-19','良質','りょうしつ','양질; 품질이 좋음','品質・内容などが優れていて良いさま。','良質な学習データを集めるには、量だけでなく内容の検証も欠かせない。','양질의 학습 데이터를 모으려면 양뿐 아니라 내용 검증도 빠뜨릴 수 없다.'),
('n1-1699','2026-12-19','聞き取り','ききとり','듣고 이해하기; 청취; 듣기 조사','話・音声を聞いて内容を理解すること。また、相手から事情を聞き取ること。','関係者への聞き取りを行い、事故当時の状況を確認した。','관계자에게 청취 조사를 실시해 사고 당시 상황을 확인했다.');
INSERT INTO _n1_b6_words_0121(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-1986','2026-12-20','身なり','みなり','옷차림; 외모; 차림새','衣服・髪型などを含めた外見の様子。','面接なので、清潔感のある身なりを心がけた。','면접이라 깔끔한 옷차림을 신경 썼다.'),
('n1-2136','2026-12-20','粘り','ねばり','끈기; 점성; 끈끈함','粘りつく性質。また、簡単にはあきらめない強さ。','最後まで粘りを見せて逆転した。','끝까지 끈기를 보여 역전했다.'),
('n1-2221','2026-12-20','思い付き','おもいつき','생각남; 착상; 즉흥적인 아이디어','ふと頭に浮かんだ考え・アイデア。','単なる思い付きではなく、十分に検討した案だ。','단순한 즉흥적 생각이 아니라 충분히 검토한 안이다.'),
('n1-2224','2026-12-20','振り出し','ふりだし','출발점; 처음; 원점','物事の出発点・最初の状態。','交渉が決裂して話は振り出しに戻った。','협상이 결렬되어 이야기는 원점으로 돌아갔다.'),
('n1-2280','2026-12-20','気兼ね','きがね','눈치 봄; 사양함; 부담스러워함','相手に迷惑をかけないかなどと気を遣い、行動を遠慮すること。','親しい友人の家なので、気兼ねなく過ごすことができた。','친한 친구 집이라 눈치 보지 않고 편하게 지낼 수 있었다.'),
('n1-2284','2026-12-20','裏返し','うらがえし','뒤집음; 뒤집힌 상태; 정반대의 표현','表と裏を逆にすること。また、表面に現れたものが本心などとは反対の形であること。','その強い言葉は、不安の裏返しかもしれない。','그 강한 말은 불안감이 반대로 드러난 것일지도 모른다.'),
('n1-2316','2026-12-20','出直し','でなおし','다시 시작함; 처음부터 새로 함; 재출발','いったん失敗・中断したことを、改めて最初からやり直すこと。','今回は準備不足だったので、一から出直しだ。','이번에는 준비가 부족했으니 처음부터 다시 시작해야 한다.'),
('n1-2362','2026-12-20','値打ち','ねうち','가치; 값어치; 가격','物事が持つ価値・有用性。また、その価格。','この経験はお金では測れない値打ちがある。','이 경험은 돈으로 잴 수 없는 가치가 있다.'),
('n1-2536','2026-12-20','並びに','ならびに','및; 그리고; 아울러','同種の事柄を並べて結び付ける改まった接続詞。および。','氏名並びに住所を記入してください。','성명 및 주소를 기입해 주세요.'),
('n1-2560','2026-12-20','戸締り','とじまり','문단속; 문을 잠금','戸や窓を閉めて鍵をかけること。','外出前に戸締りを確認した。','외출 전에 문단속을 확인했다.'),
('n1-2580','2026-12-20','駆け足','かけあし','구보; 달리기; 빠르게 진행함','走って進むこと。また、物事を急いで進めること。','時間がないので説明を駆け足で進めた。','시간이 없어서 설명을 빠르게 진행했다.'),
('n1-2597','2026-12-20','嘘つき','うそつき','거짓말쟁이','よく嘘をつく人。','一度の失敗だけで人を嘘つきと決めつけてはいけない。','한 번의 실수만으로 사람을 거짓말쟁이라고 단정해서는 안 된다.'),
('n1-2630','2026-12-20','手掛かり','てがかり','실마리; 단서; 단초','問題・事件などを解決するための糸口となるもの。','警察は現場で重要な手掛かりを見つけた。','경찰은 현장에서 중요한 단서를 발견했다.'),
('n1-2672','2026-12-20','善し悪し','よしあし','좋고 나쁨; 장단점; 적합 여부','良いことと悪いこと。物事の長所短所や適否。','新制度の善し悪しは実際に運用してみないと分からない。','새 제도의 장단점은 실제로 운영해 보지 않으면 알 수 없다.'),
('n1-2689','2026-12-20','心掛け','こころがけ','마음가짐; 평소의 태도','物事に対する心の持ち方や普段からの姿勢。','日頃の心掛けが安全につながる。','평소의 마음가짐이 안전으로 이어진다.'),
('n1-2730','2026-12-20','束の間','つかのま','잠깐; 아주 짧은 시간','ごく短い時間。','束の間の休息を楽しんだ。','잠깐의 휴식을 즐겼다.'),
('n1-2980','2026-12-20','申し分','もうしぶん','불만; 흠; 부족한 점','不満に思う点、欠点として指摘したい点。','性能も価格も申し分ない。','성능도 가격도 흠잡을 데가 없다.'),
('n1-2510','2026-12-20','仕付ける','しつける','예절을 가르치다; 훈육하다; 버릇을 들이다','礼儀や生活上の決まりを教え、習慣として身につけさせる。','子どもに公共の場でのマナーをきちんと仕付ける。','아이에게 공공장소에서의 예절을 제대로 가르친다.'),
('n1-0337','2026-12-20','言い訳','いいわけ','변명; 핑계; 해명','自分の失敗・責任・行動について、事情や理由を説明して正当化しようとすること。また、その説明。','失敗の原因を他人のせいにして言い訳するより、改善策を考えるほうが建設的だ。','실패 원인을 남 탓으로 돌리며 변명하기보다 개선책을 생각하는 편이 건설적이다.'),
('n1-0401','2026-12-20','付属','ふぞく','부속; 부속됨; 딸림','中心となるものに付き従っていること。また、そのものや組織。','製品には充電用のケーブルが付属しているので、別に購入する必要はない。','제품에는 충전용 케이블이 부속되어 있어 따로 구입할 필요가 없다.'),
('n1-0402','2026-12-21','描写','びょうしゃ','묘사; 그려 냄','人・物・景色・感情などの様子を、文章・言葉・絵などで具体的に表すこと。','この小説は、災害後の町の様子を細かく描写していて非常に印象的だ。','이 소설은 재해 후 마을의 모습을 세밀하게 묘사하고 있어 매우 인상적이다.'),
('n1-0403','2026-12-21','相場','そうば','시세; 시장 가격; 통상적인 수준','市場で取引される物・株・通貨などのおおよその価格。また、一般に妥当とされる価格や程度。','中古住宅を買う前に、その地域の相場を調べておいたほうがよい。','중고 주택을 사기 전에 그 지역의 시세를 조사해 두는 편이 좋다.'),
('n1-0404','2026-12-21','分裂','ぶんれつ','분열; 갈라짐','一つだった集団・組織・考えなどが、対立などによって複数に分かれること。','方針をめぐる対立が深まり、団体は最終的に二つの派閥へ分裂した。','방침을 둘러싼 대립이 심해져 단체는 결국 두 파벌로 분열되었다.'),
('n1-0407','2026-12-21','心地','ここち','기분; 느낌; 감촉','身体や心で感じる気分・感覚。『居心地』『寝心地』など複合語でもよく使う。','窓から風が入り、静かな音楽も流れていて、とても心地のよい空間だった。','창문으로 바람이 들어오고 잔잔한 음악도 흘러 매우 기분 좋은 공간이었다.'),
('n1-0413','2026-12-21','反発','はんぱつ','반발; 반대; 튕겨 나감','意見・方針などに強く反対すること。また、物理的に押されたものが跳ね返ること。','十分な説明なしに制度を変更したため、現場から強い反発を受けた。','충분한 설명 없이 제도를 변경해 현장으로부터 강한 반발을 샀다.'),
('n1-0414','2026-12-21','変動','へんどう','변동; 변화; 오르내림','価格・数値・状況などが一定せず、時間とともに動き変わること。','為替相場の変動が大きいため、海外取引の利益を予測しにくい。','환율 시세의 변동이 커 해외 거래의 이익을 예측하기 어렵다.'),
('n1-0420','2026-12-21','体力','たいりょく','체력; 신체적인 힘','身体を動かし、仕事や運動などを続けるための肉体的な力や持久力。','夜勤が続く仕事なので、知識や経験だけでなく一定の体力も求められる。','야간 근무가 계속되는 일이어서 지식과 경험뿐 아니라 일정한 체력도 요구된다.'),
('n1-0422','2026-12-21','真理','しんり','진리; 참된 이치','時代や立場にかかわらず正しいと考えられる根本的な道理・事実。','科学は絶対的な真理を宣言するより、証拠に基づいて仮説を検証し続ける営みだ。','과학은 절대적인 진리를 선언하기보다 증거에 근거해 가설을 계속 검증하는 활동이다.'),
('n1-0423','2026-12-21','団結','だんけつ','단결; 단합','複数の人が共通の目的のために心や力を一つに合わせること。','危機を乗り越えるためには、部署の違いを超えて社員が団結する必要がある。','위기를 극복하려면 부서의 차이를 넘어 직원들이 단결할 필요가 있다.'),
('n1-0424','2026-12-21','意向','いこう','의향; 생각; 뜻','あることについて、本人や組織がどうしたいと考えているかという意思・考え。','本人の意向を確認せずに、会社側だけで異動先を決めるべきではない。','본인의 의향을 확인하지 않고 회사 측만으로 이동 부서를 정해서는 안 된다.'),
('n1-0431','2026-12-21','放置','ほうち','방치; 그대로 내버려 둠','問題・物・状態などに必要な対応をせず、そのままにしておくこと。','小さな不具合でも放置すると、後で大きな障害につながる可能性がある。','작은 오류라도 방치하면 나중에 큰 장애로 이어질 가능성이 있다.'),
('n1-0437','2026-12-21','黄金','おうごん','황금; 금; 매우 귀중한 것','金色に輝く金。また、比喩的に非常に価値の高いものや最も栄えた時代を表す。','その作家の三十代は、代表作を次々と発表した創作の黄金時代だった。','그 작가의 30대는 대표작을 잇달아 발표한 창작의 황금기였다.'),
('n1-0443','2026-12-21','野生','やせい','야생; 자연 상태','人に飼育・栽培されず、自然の中で生育していること。また、その動植物。','野生動物に餌を与えると、生態系や人との距離感に悪影響を及ぼすことがある。','야생동물에게 먹이를 주면 생태계나 사람과의 거리감에 악영향을 줄 수 있다.'),
('n1-0446','2026-12-21','居住','きょじゅう','거주; 거주함','一定の場所に住み、生活の拠点を置くこと。','この制度は市内に一年以上居住している人を対象としている。','이 제도는 시내에 1년 이상 거주하고 있는 사람을 대상으로 한다.'),
('n1-0447','2026-12-21','誘導','ゆうどう','유도; 안내하여 이끎','人・車・物などを目的の方向や場所へ導くこと。また、考えや行動を一定方向へ導くこと。','係員の誘導に従い、混雑しない出口から順番に退場してください。','직원의 안내에 따라 혼잡하지 않은 출구부터 순서대로 퇴장해 주세요.'),
('n1-0449','2026-12-21','主導','しゅどう','주도; 주도권을 잡음','中心となって計画・交渉・活動などを導き進めること。','今回の改革は現場ではなく経営陣が主導して進めることになった。','이번 개혁은 현장이 아니라 경영진이 주도하여 진행하기로 했다.'),
('n1-0452','2026-12-21','退治','たいじ','퇴치; 없앰','害を与える生き物・悪者・問題などを追い払ったり、取り除いたりすること。','農家は作物を守るため、畑に増えた害虫の退治に追われている。','농가는 농작물을 지키기 위해 밭에 늘어난 해충 퇴치에 바쁘다.'),
('n1-0453','2026-12-21','照明','しょうめい','조명; 빛을 비춤','光を当てて場所や物を明るくすること。また、そのための設備・光。','展示品を傷めないよう、照明の明るさと当てる角度を細かく調整した。','전시품이 손상되지 않도록 조명의 밝기와 비추는 각도를 세밀하게 조정했다.'),
('n1-0460','2026-12-21','結合','けつごう','결합; 결합함','二つ以上の物・要素・組織などが結び付いて一つになること。','複数のデータを一つの表に結合してから、重複項目を削除した。','여러 데이터를 하나의 표로 결합한 뒤 중복 항목을 삭제했다.'),
('n1-0461','2026-12-21','加工','かこう','가공; 가공 처리','原料・材料に手を加えて、形・性質・用途などを変え、製品や利用しやすい状態にすること。','収穫した果物の一部は、そのまま販売せずジュースやジャムに加工される。','수확한 과일 일부는 그대로 판매하지 않고 주스나 잼으로 가공된다.');
INSERT INTO _n1_b6_words_0121(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-0462','2026-12-22','調和','ちょうわ','조화; 균형 있게 어울림','複数の要素が互いに違和感なく釣り合い、全体としてよくまとまっていること。','新しい建物は、周囲の歴史的な景観と調和するよう高さや色が工夫されている。','새 건물은 주변의 역사적 경관과 조화를 이루도록 높이와 색이 조정되어 있다.'),
('n1-0464','2026-12-22','発掘','はっくつ','발굴; 찾아냄','地中に埋もれた遺物などを掘り出すこと。また、まだ知られていない人材・作品・価値などを見つけ出すこと。','若い才能を発掘するため、全国規模のコンテストが開催された。','젊은 인재를 발굴하기 위해 전국 규모의 콘테스트가 개최되었다.'),
('n1-0466','2026-12-22','要望','ようぼう','요구; 요청; 바라는 사항','相手に実現してほしいと強く望む内容・要求。','利用者からの要望をすべて実現するのではなく、優先順位を付けて対応する。','이용자의 요구를 모두 실현하는 것이 아니라 우선순위를 정해 대응한다.'),
('n1-0470','2026-12-22','先行','せんこう','선행; 앞서감; 먼저 실시함','他より先に進むこと、または予定された全体より先に一部を実施すること。','全国展開の前に、三つの地域で新サービスを先行して開始する。','전국 전개에 앞서 세 지역에서 새 서비스를 먼저 시작한다.'),
('n1-0471','2026-12-22','介護','かいご','개호; 간병; 돌봄','高齢者や病気・障害などで日常生活に支援が必要な人の生活を助け、世話をすること。','仕事と家族の介護を両立できるよう、短時間勤務制度を利用している。','일과 가족 간병을 병행할 수 있도록 단시간 근무 제도를 이용하고 있다.'),
('n1-0474','2026-12-22','区間','くかん','구간; 일정 지점 사이','二つの地点の間として区切られた範囲。特に道路・鉄道・距離などについていう。','工事のため、この区間では週末の列車がすべて運休する。','공사 때문에 이 구간에서는 주말 열차가 모두 운휴한다.'),
('n1-0476','2026-12-22','指令','しれい','지령; 명령; 지시','上位の組織・指揮者などが、下位の組織や担当者に正式な命令・指示を出すこと。また、その内容。','中央本部から避難支援を開始するよう各支部に指令が出された。','중앙본부에서 대피 지원을 시작하라는 지령이 각 지부에 내려졌다.'),
('n1-0480','2026-12-22','不在','ふざい','부재; 자리에 없음','その場所に本人がいないこと。また、必要な人・要素などが存在しないこと。','担当者が不在のため、詳しい回答は午後になるとのことだった。','담당자가 부재중이라 자세한 답변은 오후가 된다고 했다.'),
('n1-0481','2026-12-22','無断','むだん','무단; 허가 없이','事前に許可・承諾・連絡を得ないこと。','社内資料を無断で外部へ持ち出すことは禁止されている。','사내 자료를 무단으로 외부에 반출하는 것은 금지되어 있다.'),
('n1-0482','2026-12-22','護衛','ごえい','호위; 경호; 보호','重要な人・物・車両などに付き添い、危険から守ること。また、その役目を担う人や部隊。','要人の移動には複数の警備員が同行し、周囲を護衛した。','요인의 이동에는 여러 경비원이 동행해 주변을 호위했다.'),
('n1-0486','2026-12-22','分子','ぶんし','분자; 분수의 위 숫자; 분자 단위','化学では物質の性質を保つ最小単位。数学では分数の上側の数をいう。','水の分子は、水素原子二個と酸素原子一個から構成されている。','물 분자는 수소 원자 두 개와 산소 원자 한 개로 이루어져 있다.'),
('n1-0491','2026-12-22','在庫','ざいこ','재고; 보유 상품','販売・使用に備えて倉庫や店舗などに保管されている商品・材料の数量や物そのもの。','在庫が残り少なくなった商品は、自動的に発注される仕組みになっている。','재고가 얼마 남지 않은 상품은 자동으로 발주되는 구조로 되어 있다.'),
('n1-0492','2026-12-22','進路','しんろ','진로; 앞으로 나아갈 길','進んでいく道筋。また、進学・就職など将来の生き方や方向。','卒業後の進路について迷っていたので、大学の相談窓口を利用した。','졸업 후 진로를 고민하고 있어 대학 상담 창구를 이용했다.'),
('n1-0493','2026-12-22','走行','そうこう','주행; 달림','自動車・列車・自転車などの車両が道や線路を走ること。','雪道を走行する際は、急な加速やブレーキを避ける必要がある。','눈길을 주행할 때는 급가속이나 급제동을 피할 필요가 있다.'),
('n1-0498','2026-12-22','該当','がいとう','해당; 조건에 들어맞음','定められた条件・分類・範囲などにちょうど当てはまること。','次の条件に該当する人は、追加書類を提出する必要がある。','다음 조건에 해당하는 사람은 추가 서류를 제출할 필요가 있다.'),
('n1-0501','2026-12-22','武力','ぶりょく','무력; 군사력','軍隊・武器などによって行使される軍事的な力。','国際的な争いを武力ではなく外交によって解決する努力が求められる。','국제적인 분쟁을 무력이 아니라 외교로 해결하려는 노력이 요구된다.'),
('n1-0505','2026-12-22','区画','くかく','구획; 구역','土地・建物・空間などを境界によって分けること。また、その分けられた一区域。','避難所では家族ごとに区画を分け、最低限の私的空間を確保している。','대피소에서는 가족별로 구획을 나누어 최소한의 사적 공간을 확보하고 있다.'),
('n1-0509','2026-12-22','主演','しゅえん','주연; 주연을 맡음','映画・演劇・ドラマなどで中心となる役を演じること。また、その俳優。','若手俳優が話題の映画で初めて主演を務めることになった。','젊은 배우가 화제의 영화에서 처음으로 주연을 맡게 되었다.'),
('n1-0511','2026-12-22','発作','ほっさ','발작; 증상이 갑자기 나타남','病気の症状が突然強く現れること。感情・行動が突発的に起こる場合にも使う。','激しい発作が起きた場合に備えて、患者は常に薬を携帯している。','심한 발작이 일어날 경우에 대비해 환자는 항상 약을 휴대하고 있다.'),
('n1-0512','2026-12-22','運賃','うんちん','운임; 교통요금; 운송료','人や荷物を鉄道・バス・船などで運ぶことに対して支払う料金。','燃料費の上昇を受け、来月から一部路線の運賃が引き上げられる。','연료비 상승으로 다음 달부터 일부 노선의 운임이 인상된다.'),
('n1-0514','2026-12-23','視覚','しかく','시각; 보는 감각','目によって光・色・形・動きなどを感じ取る感覚。','色だけで状態を区別すると、視覚に障害のある利用者には分かりにくい場合がある。','색만으로 상태를 구분하면 시각 장애가 있는 이용자에게는 이해하기 어려울 수 있다.'),
('n1-0519','2026-12-23','回路','かいろ','회로; 전기 신호의 통로','電流・電気信号が流れるよう、部品や導線を接続して作られた通路・仕組み。','回路の一部が過熱したため、安全装置が働いて電源が自動的に切れた。','회로 일부가 과열되어 안전장치가 작동해 전원이 자동으로 꺼졌다.'),
('n1-0520','2026-12-23','丁目','ちょうめ','초메; 일본 주소의 구획 단위','日本の住所表示で、市街地の町をさらに分ける区画の単位。数字を伴って『一丁目』などと使う。','会社は駅から徒歩五分の中央区三丁目に移転した。','회사는 역에서 도보 5분 거리인 주오구 3초메로 이전했다.'),
('n1-0526','2026-12-23','行進','こうしん','행진; 행군','大勢の人が列を整えて、同じ方向へ歩いて進むこと。','式典では参加者が旗を掲げ、音楽に合わせて会場内を行進した。','행사에서는 참가자들이 깃발을 들고 음악에 맞춰 행사장 안을 행진했다.'),
('n1-0530','2026-12-23','中立','ちゅうりつ','중립; 어느 쪽에도 치우치지 않음','対立する双方のどちらにも偏らず、特定の側を支持しない立場。','調査委員会には、当事者から独立した中立的な立場が求められる。','조사위원회에는 당사자로부터 독립된 중립적인 입장이 요구된다.'),
('n1-0531','2026-12-23','墓地','はかち','묘지; 무덤이 있는 곳','墓を設け、遺骨・遺体を埋葬するための土地。一般には『ぼち』とも読む。','古い墓地の周辺を整備し、歩きやすい参道を作る工事が始まった。','오래된 묘지 주변을 정비해 걷기 쉬운 참배길을 만드는 공사가 시작되었다.'),
('n1-0533','2026-12-23','反撃','はんげき','반격; 역공','攻撃を受けた側が、相手に向かって攻め返すこと。','前半は押されていたチームが後半に反撃し、試合を引き分けに持ち込んだ。','전반에 밀리던 팀이 후반에 반격해 경기를 무승부로 만들었다.'),
('n1-0535','2026-12-23','青春','せいしゅん','청춘; 젊은 시절','人生の中で若く、心身ともに活力に満ちた時期。','青春時代を過ごした町を二十年ぶりに訪れ、懐かしい気持ちになった。','청춘 시절을 보낸 도시를 20년 만에 방문해 그리운 기분이 들었다.'),
('n1-0538','2026-12-23','合成','ごうせい','합성; 둘 이상을 합쳐 만듦','二つ以上の物質・音・画像・要素などを組み合わせ、一つのものを作ること。','複数の写真を合成して、実際には存在しない風景を作り出した。','여러 사진을 합성해 실제로는 존재하지 않는 풍경을 만들어 냈다.'),
('n1-0541','2026-12-23','品種','ひんしゅ','품종; 종류','動植物を性質・形質によって分けた種類。転じて、品物の種類をいうこともある。','病気に強く収穫量も多い新品種の開発が各地で進められている。','병에 강하고 수확량도 많은 신품종 개발이 각지에서 진행되고 있다.'),
('n1-0548','2026-12-23','物体','ぶったい','물체; 물리적으로 존재하는 대상','一定の形や大きさをもち、空間を占めて存在する物。','センサーは前方の物体との距離を測定し、衝突の危険を知らせる。','센서는 전방 물체와의 거리를 측정해 충돌 위험을 알려 준다.'),
('n1-0553','2026-12-23','養成','ようせい','양성; 교육·훈련하여 길러 냄','知識や技能を身につけさせ、特定の分野で役立つ人材を育てること。','不足している専門技術者を養成するため、新しい研修制度が導入された。','부족한 전문 기술자를 양성하기 위해 새로운 연수 제도가 도입되었다.'),
('n1-0555','2026-12-23','愛想','あいそ','붙임성; 싹싹한 태도; 호감','人に接するときの感じのよい態度や応対。また、人に対する好意・愛情。','彼は口数こそ少ないが、客には愛想よく応対するので評判がいい。','그는 말수는 적지만 손님에게는 붙임성 있게 응대해 평판이 좋다.'),
('n1-0562','2026-12-23','混同','こんどう','혼동; 서로 다른 것을 뒤섞어 생각함','本来区別すべき複数のものを、同じもののように取り違えたり混ぜて考えたりすること。','似た名称の制度を混同すると、申請先を間違えるおそれがある。','이름이 비슷한 제도를 혼동하면 신청처를 잘못 선택할 우려가 있다.'),
('n1-0565','2026-12-23','対話','たいわ','대화; 서로 의견을 주고받음','向き合って互いに話し、考えや意見を伝え合うこと。','住民との対話を重ねながら、再開発計画を見直していく必要がある。','주민과의 대화를 거듭하면서 재개발 계획을 재검토할 필요가 있다.'),
('n1-0566','2026-12-23','細工','さいく','세공; 정교하게 손질해 만듦; 세공품','手先を使って材料を細かく加工し、物を作ったり装飾を施したりすること。また、その作った物。','この箱には職人による精巧な木工細工が施されている。','이 상자에는 장인이 만든 정교한 목공 세공이 되어 있다.'),
('n1-0569','2026-12-23','用紙','ようし','용지; 특정 용도의 종이·서식','申請・印刷・記入など、特定の目的に用いる紙。','申請用紙に必要事項を記入し、窓口へ提出してください。','신청 용지에 필요한 사항을 기입해 창구에 제출해 주세요.'),
('n1-0573','2026-12-23','世帯','せたい','가구; 함께 생활하는 한 단위','住居と生計を共にする人々のまとまり。また、その生活単位を数える語。','この地域では単身世帯の割合が年々高くなっている。','이 지역에서는 1인 가구의 비율이 해마다 높아지고 있다.'),
('n1-0579','2026-12-23','利点','りてん','이점; 유리한 점','他と比べて有利・便利・有益である点。','在宅勤務の最大の利点は、通勤に使っていた時間を有効に使えることだ。','재택근무의 가장 큰 이점은 통근에 쓰던 시간을 효율적으로 활용할 수 있다는 것이다.'),
('n1-0582','2026-12-23','個々','ここ','개개; 각각; 하나하나','一つ一つ、それぞれ別々のもの・人。','制度を一律に適用するのではなく、個々の事情を考慮する必要がある。','제도를 일률적으로 적용하지 말고 개개의 사정을 고려할 필요가 있다.');
INSERT INTO japanese_words(word,reading,meaning_ko,meaning_ja,jlpt_level_id,ai_status,note) SELECT s.word,s.reading,s.meaning_ko,s.meaning_ja,(SELECT id FROM jlpt_levels WHERE code='N1'),'reviewed','JLPT N1 batch 2026-12-10..2026-12-23' FROM _n1_b6_words_0121 s WHERE NOT EXISTS (SELECT 1 FROM japanese_words w WHERE w.word=s.word AND w.reading=s.reading AND w.deleted_at IS NULL);
INSERT INTO _n1_b6_map_0121(source_key,word_id) SELECT s.source_key,MIN(w.id) FROM _n1_b6_words_0121 s JOIN japanese_words w ON w.word=s.word AND w.reading=s.reading AND w.deleted_at IS NULL GROUP BY s.source_key;
