INSERT INTO japanese_jlpt_daily_words(session_id,word_id,item_kind) SELECT ds.id,m.word_id,'new' FROM _n1_b6_words_0121 s JOIN _n1_b6_map_0121 m ON m.source_key=s.source_key JOIN japanese_jlpt_daily_sessions ds ON ds.study_date=s.study_date JOIN japanese_jlpt_study_plans p ON p.id=ds.plan_id WHERE p.plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-10','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1819","prompt":"「乃至」の読み方として最も適切なものを選びなさい。","options":["いぜん","おもなる","りょうしつ","ないし"],"answer":"ないし","explanationKo":"「乃至」는 「ないし」라고 읽는다. 뜻은 ~에서 ~까지; 또는; 내지이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-10','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1761","prompt":"「或いは」の読み方として最も適切なものを選びなさい。","options":["むち","くうふく","あるいは","ゆうい"],"answer":"あるいは","explanationKo":"「或いは」는 「あるいは」라고 읽는다. 뜻은 혹은; 또는; 아니면이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-10','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1830","prompt":"「若しくは」の読み方として最も適切なものを選びなさい。","options":["こうちょう","もしくは","いくた","ないし"],"answer":"もしくは","explanationKo":"「若しくは」는 「もしくは」라고 읽는다. 뜻은 혹은; 또는이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-10','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-1694","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n専門用語の（　）が多いため、資料の末尾に一覧を付けた。","options":["略語","視覚","軽減","農耕"],"answer":"略語","explanationKo":"문맥상 「略語」가 가장 자연스럽다. 약어; 준말라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-10','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-1711","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n社長は現場を訪れ、復旧作業に当たる社員を（　）した。","options":["予言","勢力","国連","激励"],"answer":"激励","explanationKo":"문맥상 「激励」가 가장 자연스럽다. 격려; 힘을 북돋움라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-10','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-1886","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n部長は四月付で大阪支社へ（　）することになった。","options":["共産","嘘つき","転任","工学"],"answer":"転任","explanationKo":"문맥상 「転任」가 가장 자연스럽다. 전임; 다른 근무지·직책으로 이동함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-10','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-1926","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n長年の実績が評価され、彼は取締役会から厚い（　）を得ている。","options":["用紙","信任","裏返し","不在"],"answer":"信任","explanationKo":"문맥상 「信任」가 가장 자연스럽다. 신임; 믿고 맡김라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-10','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-1985","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n悪天候のため登山者が山中で（　）した。","options":["遭難","品種","屈折","窒息"],"answer":"遭難","explanationKo":"문맥상 「遭難」가 가장 자연스럽다. 조난; 재난을 당함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
