INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-10','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2969","prompt":"「中心となる。主要な。」という意味に最も近い語を選びなさい。","options":["重なる","良質","日頃","相応"],"answer":"重なる","explanationKo":"「重なる」의 핵심 의미는 주된; 주요한; 중요한이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
