INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-10','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2113","prompt":"「不正・理不尽なことなどに激しく腹を立てること。」という意味に最も近い語を選びなさい。","options":["農場","身なり","憤慨","暴力"],"answer":"憤慨","explanationKo":"「憤慨」의 핵심 의미는 분개; 몹시 화냄이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
