INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-10','grammar',1,'〜あってこそ','{"pattern":"〜あってこそ","meaningKo":"〜이 있어야만","explanation":"〜あってこそ는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"利用者の信頼があってこそ、制度は安定して運用できる。","ko":"문맥에서 〜이 있어야만의 의미로 쓰였다."},{"ja":"十分な準備があってこそ、現場で冷静に判断できる。","ko":"이 문장도 〜이 있어야만의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-10','grammar',2,'〜いかんによって','{"pattern":"〜いかんによって","meaningKo":"〜여하에 따라","explanation":"〜いかんによって는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"検証の結果いかんによって、導入時期を変更する。","ko":"문맥에서 〜여하에 따라의 의미로 쓰였다."},{"ja":"交渉の進展いかんによって、追加予算を検討する。","ko":"이 문장도 〜여하에 따라의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-10','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n利用者の信頼が（　）、制度は安定して運用できる。","options":["〜あってこそ","〜こそすれ","〜つ〜つ","〜にほかならない"],"answer":"〜あってこそ","explanationKo":"문맥상 〜이 있어야만를 나타내는 「〜あってこそ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-10','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n検証の結果（　）、導入時期を変更する。","options":["〜ことなしに","〜でなくてなんだろう","〜にも増して","〜いかんによって"],"answer":"〜いかんによって","explanationKo":"문맥상 〜여하에 따라를 나타내는 「〜いかんによって」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-10','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n需要が落ち着く（　）、注文はさらに増えた。","options":["〜と相まって","〜ばこそ","〜かと思いきや","〜こととて"],"answer":"〜かと思いきや","explanationKo":"문맥상 〜인가 했더니를 나타내는 「〜かと思いきや」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-10','reading',1,'専門用語を言い換える','{"passage":"専門的な内容を相手に合わせて説明することには、知識の異なる人とも判断材料を共有できることという意義がある。しかし、簡単にしすぎると重要な条件まで失われることにも注意しなければならない。判断の目的と前提を関係者で共有し、結果に応じて方法を見直せるようにしておく必要がある。ゆえに、核心となる条件を残したまま表現を調整することが重要なのである。","questions":[{"prompt":"「専門用語を言い換える」について筆者が最も重要だと考えることは何か。","options":["核心となる条件を残したまま表現を調整すること","最初の結論を必ず維持すること","前提を関係者に知らせないこと","結果を確認せず次へ進むこと"],"answer":"核心となる条件を残したまま表現を調整すること","explanationKo":"본문에서는 核心となる条件を残したまま表現を調整すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意点として挙げられているものは何か。","options":["簡単にしすぎると重要な条件まで失われること","目的を共有すると効果が消えること","記録を残すと判断が遅れること","関係者を増やせば問題がなくなること"],"answer":"簡単にしすぎると重要な条件まで失われること","explanationKo":"주의해야 할 점은 簡単にしすぎると重要な条件まで失われること 가능성이다."},{"prompt":"本文の内容と合うものはどれか。","options":["知識の異なる人とも判断材料を共有できること","方法は結果に関係なく固定すべきだ","判断の前提は示さない方がよい","実施後の見直しは不要である"],"answer":"知識の異なる人とも判断材料を共有できること","explanationKo":"専門的な内容を相手に合わせて説明すること에는 知識の異なる人とも判断材料を共有できること라는 의의가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-11','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2499","prompt":"「慣例」の読み方として最も適切なものを選びなさい。","options":["かんれい","たいりょく","ちゅうりつ","せっちゅう"],"answer":"かんれい","explanationKo":"「慣例」는 「かんれい」라고 읽는다. 뜻은 관례; 관행이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
