INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-11','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0054","prompt":"「他人や社会を従わせたり動かしたりできる政治的・社会的な力。」という意味に最も近い語を選びなさい。","options":["倍率","粉末","予言","権力"],"answer":"権力","explanationKo":"「権力」의 핵심 의미는 권력이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-11','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0123","prompt":"「職場や組織で担当して行う仕事。」という意味に最も近い語を選びなさい。","options":["仕様","工学","業務","辻褄"],"answer":"業務","explanationKo":"「業務」의 핵심 의미는 업무이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-11','grammar',1,'〜かと思いきや','{"pattern":"〜かと思いきや","meaningKo":"〜인가 했더니","explanation":"〜かと思いきや는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"問題は解決したかと思いきや、新たな不具合が見つかった。","ko":"문맥에서 〜인가 했더니의 의미로 쓰였다."},{"ja":"需要が落ち着くかと思いきや、注文はさらに増えた。","ko":"이 문장도 〜인가 했더니의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-11','grammar',2,'〜か否か','{"pattern":"〜か否か","meaningKo":"〜인지 아닌지","explanation":"〜か否か는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"提案を採用するか否か、根拠を示して判断すべきだ。","ko":"문맥에서 〜인지 아닌지의 의미로 쓰였다."},{"ja":"情報が正確か否か、複数の資料で確認する。","ko":"이 문장도 〜인지 아닌지의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-11','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n問題は解決した（　）、新たな不具合が見つかった。","options":["〜こととて","〜と相まって","〜ばこそ","〜かと思いきや"],"answer":"〜かと思いきや","explanationKo":"문맥상 〜인가 했더니를 나타내는 「〜かと思いきや」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-11','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n提案を採用する（　）、根拠を示して判断すべきだ。","options":["〜ないことには","〜まみれ","〜か否か","〜ずじまい"],"answer":"〜か否か","explanationKo":"문맥상 〜인지 아닌지를 나타내는 「〜か否か」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-11','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nここは地域（　）景勝地である。","options":["〜も同然だ","〜きっての","〜ずにはいられない","〜ならまだしも"],"answer":"〜きっての","explanationKo":"문맥상 〜중에서도 손꼽히는를 나타내는 「〜きっての」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-11','reading',1,'危機時の情報整理','{"passage":"緊急時に情報の確度と優先度を分けることには、限られた時間で重要な判断を進められることという意義がある。しかし、未確認情報を事実として広めると混乱が増すことにも注意しなければならない。判断の目的と前提を関係者で共有し、結果に応じて方法を見直せるようにしておく必要がある。ゆえに、確認済みの事実と推測を明確に区別することが重要なのである。","questions":[{"prompt":"「危機時の情報整理」について筆者が最も重要だと考えることは何か。","options":["確認済みの事実と推測を明確に区別すること","最初の結論を必ず維持すること","前提を関係者に知らせないこと","結果を確認せず次へ進むこと"],"answer":"確認済みの事実と推測を明確に区別すること","explanationKo":"본문에서는 確認済みの事実と推測を明確に区別すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意点として挙げられているものは何か。","options":["未確認情報を事実として広めると混乱が増すこと","目的を共有すると効果が消えること","記録を残すと判断が遅れること","関係者を増やせば問題がなくなること"],"answer":"未確認情報を事実として広めると混乱が増すこと","explanationKo":"주의해야 할 점은 未確認情報を事実として広めると混乱が増すこと 가능성이다."},{"prompt":"本文の内容と合うものはどれか。","options":["限られた時間で重要な判断を進められること","方法は結果に関係なく固定すべきだ","判断の前提は示さない方がよい","実施後の見直しは不要である"],"answer":"限られた時間で重要な判断を進められること","explanationKo":"緊急時に情報の確度と優先度を分けること에는 限られた時間で重要な判断を進められること라는 의의가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-12','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1705","prompt":"「近眼」の読み方として最も適切なものを選びなさい。","options":["ふぞく","きんがん","ぼうえい","そんぞく"],"answer":"きんがん","explanationKo":"「近眼」는 「きんがん」라고 읽는다. 뜻은 근시; 근시안적임이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
