INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-12','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-1884","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの製品には人工的な（　）を行わず、素材本来の色を生かしている。","options":["発言","出産","着色","窒息"],"answer":"着色","explanationKo":"문맥상 「着色」가 가장 자연스럽다. 착색; 색을 입힘라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
