INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-12','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-2076","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの電車は終点から車庫へ（　）される。","options":["振り出し","回送","人民","前提"],"answer":"回送","explanationKo":"문맥상 「回送」가 가장 자연스럽다. 회송; 빈 차량 이동; 전달라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
