INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-12','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n進行が遅れること（　）、確認を省くことはない。","options":["〜やら〜やら","〜こそすれ","〜たら最後","〜にあらず"],"answer":"〜こそすれ","explanationKo":"문맥상 〜하기는 해도를 나타내는 「〜こそすれ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-12','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n失敗を経験する（　）、技能を磨くのは難しい。","options":["〜ことなしに","〜つ〜つ","〜にかかわる","〜ようにも〜ない"],"answer":"〜ことなしに","explanationKo":"문맥상 〜하지 않고서는를 나타내는 「〜ことなしに」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-12','reading',1,'慣例を見直す基準','{"passage":"長く続く手順の必要性を検討することには、現在の目的に合わない負担を減らせることという意義がある。しかし、新しさだけを理由に廃止すると蓄積した知恵を失うことにも注意しなければならない。判断の目的と前提を関係者で共有し、結果に応じて方法を見直せるようにしておく必要がある。ゆえに、手順が守っている価値を確かめてから変えることが重要なのである。","questions":[{"prompt":"「慣例を見直す基準」について筆者が最も重要だと考えることは何か。","options":["手順が守っている価値を確かめてから変えること","最初の結論を必ず維持すること","前提を関係者に知らせないこと","結果を確認せず次へ進むこと"],"answer":"手順が守っている価値を確かめてから変えること","explanationKo":"본문에서는 手順が守っている価値を確かめてから変えること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意点として挙げられているものは何か。","options":["新しさだけを理由に廃止すると蓄積した知恵を失うこと","目的を共有すると効果が消えること","記録を残すと判断が遅れること","関係者を増やせば問題がなくなること"],"answer":"新しさだけを理由に廃止すると蓄積した知恵を失うこと","explanationKo":"주의해야 할 점은 新しさだけを理由に廃止すると蓄積した知恵を失うこと 가능성이다."},{"prompt":"本文の内容と合うものはどれか。","options":["現在の目的に合わない負担を減らせること","方法は結果に関係なく固定すべきだ","判断の前提は示さない方がよい","実施後の見直しは不要である"],"answer":"現在の目的に合わない負担を減らせること","explanationKo":"長く続く手順の必要性を検討すること에는 現在の目的に合わない負担を減らせること라는 의의가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-13','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2205","prompt":"「保温」の読み方として最も適切なものを選びなさい。","options":["せんしゅう","きかく","ほおん","じてん"],"answer":"ほおん","explanationKo":"「保温」는 「ほおん」라고 읽는다. 뜻은 보온이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
