INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-13','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2367","prompt":"「ある物質が別の物質に均一に溶けた液体。」という意味に最も近い語を選びなさい。","options":["裏返し","不在","用紙","溶液"],"answer":"溶液","explanationKo":"「溶液」의 핵심 의미는 용액이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-13','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2372","prompt":"「借りることをへりくだっていう語。」という意味に最も近い語を選びなさい。","options":["目眩","季刊","拝借","制服"],"answer":"拝借","explanationKo":"「拝借」의 핵심 의미는 빌림; 빌리다의 겸양 표현이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-13','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2374","prompt":"「他人に与えた損害を金銭や代替物などで補うこと。」という意味に最も近い語を選びなさい。","options":["新人","弁償","域外","作戦"],"answer":"弁償","explanationKo":"「弁償」의 핵심 의미는 변상; 배상이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
