INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-13','grammar',1,'〜ことなしに','{"pattern":"〜ことなしに","meaningKo":"〜하지 않고서는","explanation":"〜ことなしに는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"現場を確認することなしに、適切な対策は立てられない。","ko":"문맥에서 〜하지 않고서는의 의미로 쓰였다."},{"ja":"失敗を経験することなしに、技能を磨くのは難しい。","ko":"이 문장도 〜하지 않고서는의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-13','grammar',2,'〜こととて','{"pattern":"〜こととて","meaningKo":"〜이기 때문에","explanation":"〜こととて는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"初めてのこととて、不手際があればご容赦ください。","ko":"문맥에서 〜이기 때문에의 의미로 쓰였다."},{"ja":"急な決定のこととて、十分な説明ができなかった。","ko":"이 문장도 〜이기 때문에의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-13','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n現場を確認する（　）、適切な対策は立てられない。","options":["〜ようにも〜ない","〜ことなしに","〜つ〜つ","〜にかかわる"],"answer":"〜ことなしに","explanationKo":"문맥상 〜하지 않고서는를 나타내는 「〜ことなしに」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-13','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n初めての（　）、不手際があればご容赦ください。","options":["〜こととて","〜でなくてなんだろう","〜に忍びない","〜をいいことに"],"answer":"〜こととて","explanationKo":"문맥상 〜이기 때문에를 나타내는 「〜こととて」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-13','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n本人に理由を聞け（　）で、疑問だけが残った。","options":["〜と相まって","〜にほかならない","〜をものともせず","〜ずじまい"],"answer":"〜ずじまい","explanationKo":"문맥상 끝내 〜하지 못함를 나타내는 「〜ずじまい」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-13','reading',1,'複数案を比較する','{"passage":"異なる提案を同じ条件で評価することには、利点と負担の違いを具体的に把握できることという意義がある。しかし、評価軸が途中で変わると結論が恣意的になることにも注意しなければならない。判断の目的と前提を関係者で共有し、結果に応じて方法を見直せるようにしておく必要がある。ゆえに、比較前に目的と評価軸を共有することが重要なのである。","questions":[{"prompt":"「複数案を比較する」について筆者が最も重要だと考えることは何か。","options":["比較前に目的と評価軸を共有すること","最初の結論を必ず維持すること","前提を関係者に知らせないこと","結果を確認せず次へ進むこと"],"answer":"比較前に目的と評価軸を共有すること","explanationKo":"본문에서는 比較前に目的と評価軸を共有すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意点として挙げられているものは何か。","options":["評価軸が途中で変わると結論が恣意的になること","目的を共有すると効果が消えること","記録を残すと判断が遅れること","関係者を増やせば問題がなくなること"],"answer":"評価軸が途中で変わると結論が恣意的になること","explanationKo":"주의해야 할 점은 評価軸が途中で変わると結論が恣意的になること 가능성이다."},{"prompt":"本文の内容と合うものはどれか。","options":["利点と負担の違いを具体的に把握できること","方法は結果に関係なく固定すべきだ","判断の前提は示さない方がよい","実施後の見直しは不要である"],"answer":"利点と負担の違いを具体的に把握できること","explanationKo":"異なる提案を同じ条件で評価すること에는 利点と負担の違いを具体的に把握できること라는 의의가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-14','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2569","prompt":"「敬具」の読み方として最も適切なものを選びなさい。","options":["しんじゃ","ここち","ちょうめ","けいぐ"],"answer":"けいぐ","explanationKo":"「敬具」는 「けいぐ」라고 읽는다. 뜻은 경구; 삼가 올림(편지 맺음말)이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
