INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-14','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-2782","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの庭には落ち着いた（　）がある。","options":["雅致","勢力","国連","国土"],"answer":"雅致","explanationKo":"문맥상 「雅致」가 가장 자연스럽다. 아취; 우아한 멋; 품위 있는 정취라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
