INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-14','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2875","prompt":"「電気・ガスなど、照明や冷暖房等にかかる費用。」という意味に最も近い語を選びなさい。","options":["指揮","光熱費","類推","勘弁"],"answer":"光熱費","explanationKo":"「光熱費」의 핵심 의미는 광열비; 전기·가스 등 공공요금이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-14','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2974","prompt":"「宗教の教えを広く伝えて広めること。」という意味に最も近い語を選びなさい。","options":["宣教","作戦","新人","聞き取り"],"answer":"宣教","explanationKo":"「宣教」의 핵심 의미는 선교; 포교이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-14','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2977","prompt":"「決めた計画などを、覚悟をもって実行すること。」という意味に最も近い語を選びなさい。","options":["過ち","相場","回路","決行"],"answer":"決行","explanationKo":"「決行」의 핵심 의미는 결행; 단행이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-14','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2984","prompt":"「人や物から感じられる上品で格調の高い雰囲気。」という意味に最も近い語を選びなさい。","options":["嗜好","遠方","気品","先行"],"answer":"気品","explanationKo":"「気品」의 핵심 의미는 기품; 품격이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-14','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2987","prompt":"「数が非常に多いこと。多くの。」という意味に最も近い語を選びなさい。","options":["優位","幾多","敏感","乃至"],"answer":"幾多","explanationKo":"「幾多」의 핵심 의미는 수많은; 여러 많은이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-14','grammar',1,'〜ずじまい','{"pattern":"〜ずじまい","meaningKo":"끝내 〜하지 못함","explanation":"〜ずじまい는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"忙しさに追われ、資料を読まずじまいだった。","ko":"문맥에서 끝내 〜하지 못함의 의미로 쓰였다."},{"ja":"本人に理由を聞けずじまいで、疑問だけが残った。","ko":"이 문장도 끝내 〜하지 못함의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-14','grammar',2,'〜ずにはいられない','{"pattern":"〜ずにはいられない","meaningKo":"〜하지 않을 수 없다","explanation":"〜ずにはいられない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"その知らせを聞けば、将来を案じずにはいられない。","ko":"문맥에서 〜하지 않을 수 없다의 의미로 쓰였다."},{"ja":"見事な演技に拍手せずにはいられなかった。","ko":"이 문장도 〜하지 않을 수 없다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-14','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n忙しさに追われ、資料を読ま（　）だった。","options":["〜ずじまい","〜と相まって","〜にほかならない","〜をものともせず"],"answer":"〜ずじまい","explanationKo":"문맥상 끝내 〜하지 못함를 나타내는 「〜ずじまい」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-14','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nその知らせを聞けば、将来を案じ（　）。","options":["〜ないことには","〜にも増して","〜あってこそ","〜ずにはいられない"],"answer":"〜ずにはいられない","explanationKo":"문맥상 〜하지 않을 수 없다를 나타내는 「〜ずにはいられない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-14','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n一度妥協し（　）、同じ要求が繰り返される。","options":["〜ばこそ","〜いかんによって","〜たら最後","〜ならまだしも"],"answer":"〜たら最後","explanationKo":"문맥상 일단 〜하면 끝를 나타내는 「〜たら最後」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-14','reading',1,'失敗の原因を分ける','{"passage":"結果に影響した要因を分類することには、再発防止策を適切な対象に向けられることという意義がある。しかし、一人の責任だけにすると仕組みの問題を見逃すことにも注意しなければならない。判断の目的と前提を関係者で共有し、結果に応じて方法を見直せるようにしておく必要がある。ゆえに、個人の行動と環境の条件を分けて検討することが重要なのである。","questions":[{"prompt":"「失敗の原因を分ける」について筆者が最も重要だと考えることは何か。","options":["個人の行動と環境の条件を分けて検討すること","最初の結論を必ず維持すること","前提を関係者に知らせないこと","結果を確認せず次へ進むこと"],"answer":"個人の行動と環境の条件を分けて検討すること","explanationKo":"본문에서는 個人の行動と環境の条件を分けて検討すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意点として挙げられているものは何か。","options":["一人の責任だけにすると仕組みの問題を見逃すこと","目的を共有すると効果が消えること","記録を残すと判断が遅れること","関係者を増やせば問題がなくなること"],"answer":"一人の責任だけにすると仕組みの問題を見逃すこと","explanationKo":"주의해야 할 점은 一人の責任だけにすると仕組みの問題を見逃すこと 가능성이다."},{"prompt":"本文の内容と合うものはどれか。","options":["再発防止策を適切な対象に向けられること","方法は結果に関係なく固定すべきだ","判断の前提は示さない方がよい","実施後の見直しは不要である"],"answer":"再発防止策を適切な対象に向けられること","explanationKo":"結果に影響した要因を分類すること에는 再発防止策を適切な対象に向けられること라는 의의가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
