INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-15','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-0043","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）士は被告人を弁護するため、証拠と証言を一つずつ検討した。","options":["配偶者","差異","弁護","護衛"],"answer":"弁護","explanationKo":"문맥상 「弁護」가 가장 자연스럽다. 변호라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
