INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-15','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-0047","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n行政（　）を進めるには、手続きの簡素化だけでなく組織そのものの見直しも必要だ。","options":["改革","季刊","共和","使命"],"answer":"改革","explanationKo":"문맥상 「改革」가 가장 자연스럽다. 개혁라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-15','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-0055","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n彼の（　）は誤解を招くとして、会議後も大きな議論になった。","options":["新人","聞き取り","真理","発言"],"answer":"発言","explanationKo":"문맥상 「発言」가 가장 자연스럽다. 발언라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-15','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0072","prompt":"「国や地方公共団体が法律に基づいて行う公的な事務や政策の執行。」という意味に最も近い語を選びなさい。","options":["護衛","配偶者","行政","反発"],"answer":"行政","explanationKo":"「行政」의 핵심 의미는 행정이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-15','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0075","prompt":"「それまで行われていた制度・規則・事業などをやめてなくすこと。」という意味に最も近い語を選びなさい。","options":["蒸留","廃止","信任","没落"],"answer":"廃止","explanationKo":"「廃止」의 핵심 의미는 폐지이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-15','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0079","prompt":"「社会や集団の中で他に影響を及ぼす力。また、その力を持つ集団。」という意味に最も近い語を選びなさい。","options":["勢力","印鑑","山腹","衛生"],"answer":"勢力","explanationKo":"「勢力」의 핵심 의미는 세력; 영향력이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-15','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0087","prompt":"「新聞・テレビ・インターネットなどを通じて、社会の出来事を広く伝えること。」という意味に最も近い語を選びなさい。","options":["従事","言い訳","要望","報道"],"answer":"報道","explanationKo":"「報道」의 핵심 의미는 보도이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-15','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0093","prompt":"「株式会社における社員としての地位を細分化した単位。また、それを表す権利。」という意味に最も近い語を選びなさい。","options":["意向","青春","株式","身なり"],"answer":"株式","explanationKo":"「株式」의 핵심 의미는 주식이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-15','grammar',1,'〜たら最後','{"pattern":"〜たら最後","meaningKo":"일단 〜하면 끝","explanation":"〜たら最後는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"この情報が外部に漏れたら最後、信頼の回復は難しい。","ko":"문맥에서 일단 〜하면 끝의 의미로 쓰였다."},{"ja":"一度妥協したら最後、同じ要求が繰り返される。","ko":"이 문장도 일단 〜하면 끝의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-15','grammar',2,'〜つ〜つ','{"pattern":"〜つ〜つ","meaningKo":"〜하기도 하고 〜하기도 하며","explanation":"〜つ〜つ는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"互いに持ちつ持たれつ、長年協力してきた。","ko":"문맥에서 〜하기도 하고 〜하기도 하며의 의미로 쓰였다."},{"ja":"行きつ戻りつしながら、出口を探した。","ko":"이 문장도 〜하기도 하고 〜하기도 하며의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-15','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nこの情報が外部に漏れ（　）、信頼の回復は難しい。","options":["〜ならまだしも","〜ばこそ","〜いかんによって","〜たら最後"],"answer":"〜たら最後","explanationKo":"문맥상 일단 〜하면 끝를 나타내는 「〜たら最後」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-15','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n互いに（　）、長年協力してきた。","options":["〜まみれ","〜かと思いきや","〜つ〜つ","〜にあらず"],"answer":"〜つ〜つ","explanationKo":"문맥상 〜하기도 하고 〜하기도 하며를 나타내는 「〜つ〜つ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-15','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n危険を承知で人を救う行為は、勇気（　）。","options":["〜か否か","〜でなくてなんだろう","〜にかかわる","〜も同然だ"],"answer":"〜でなくてなんだろう","explanationKo":"문맥상 〜이 아니고 무엇이겠는가를 나타내는 「〜でなくてなんだろう」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-15','reading',1,'委託先との責任分担','{"passage":"外部の組織と担当範囲を定めることには、問題発生時の連絡と対応を速められることという意義がある。しかし、契約上の境界だけを重視すると協力が遅れることにも注意しなければならない。判断の目的と前提を関係者で共有し、結果に応じて方法を見直せるようにしておく必要がある。ゆえに、責任範囲と共同対応の条件を同時に決めることが重要なのである。","questions":[{"prompt":"「委託先との責任分担」について筆者が最も重要だと考えることは何か。","options":["責任範囲と共同対応の条件を同時に決めること","最初の結論を必ず維持すること","前提を関係者に知らせないこと","結果を確認せず次へ進むこと"],"answer":"責任範囲と共同対応の条件を同時に決めること","explanationKo":"본문에서는 責任範囲と共同対応の条件を同時に決めること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意点として挙げられているものは何か。","options":["契約上の境界だけを重視すると協力が遅れること","目的を共有すると効果が消えること","記録を残すと判断が遅れること","関係者を増やせば問題がなくなること"],"answer":"契約上の境界だけを重視すると協力が遅れること","explanationKo":"주의해야 할 점은 契約上の境界だけを重視すると協力が遅れること 가능성이다."},{"prompt":"本文の内容と合うものはどれか。","options":["問題発生時の連絡と対応を速められること","方法は結果に関係なく固定すべきだ","判断の前提は示さない方がよい","実施後の見直しは不要である"],"answer":"問題発生時の連絡と対応を速められること","explanationKo":"外部の組織と担当範囲を定めること에는 問題発生時の連絡と対応を速められること라는 의의가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-16','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0117","prompt":"「作戦」の読み方として最も適切なものを選びなさい。","options":["おおすじ","さくせん","ごうせい","ぎょうむ"],"answer":"さくせん","explanationKo":"「作戦」는 「さくせん」라고 읽는다. 뜻은 작전; 전략이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-16','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0119","prompt":"「防衛」の読み方として最も適切なものを選びなさい。","options":["ぼうえい","はれつ","そうさ","めんかい"],"answer":"ぼうえい","explanationKo":"「防衛」는 「ぼうえい」라고 읽는다. 뜻은 방위; 방어이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-16','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0120","prompt":"「運営」の読み方として最も適切なものを選びなさい。","options":["ふっこう","はいりょ","しゅどう","うんえい"],"answer":"うんえい","explanationKo":"「運営」는 「うんえい」라고 읽는다. 뜻은 운영; 경영이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-16','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-0125","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n通信技術の発達は、人々の情報交換の方法に（　）をもたらした。","options":["区画","政策","革命","放置"],"answer":"革命","explanationKo":"문맥상 「革命」가 가장 자연스럽다. 혁명; 획기적 변화라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-16','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-0127","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n意見が対立しても、（　）によって相手を従わせることは許されない。","options":["慣用","暴力","在庫","個々"],"answer":"暴力","explanationKo":"문맥상 「暴力」가 가장 자연스럽다. 폭력라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-16','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-0131","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n新しい（　）は、経済対策を最優先課題として掲げた。","options":["内閣","優越","減点","改革"],"answer":"内閣","explanationKo":"문맥상 「内閣」가 가장 자연스럽다. 내각라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-16','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-0184","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n王政が廃止された後、その国は（　）制へ移行した。","options":["指揮","復興","配慮","共和"],"answer":"共和","explanationKo":"문맥상 「共和」가 가장 자연스럽다. 공화; 공화정라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-16','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-0185","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n会場は試合終了直前の逆転劇に（　）し、大きな歓声に包まれた。","options":["真理","墓地","興奮","聞き取り"],"answer":"興奮","explanationKo":"문맥상 「興奮」가 가장 자연스럽다. 흥분라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-16','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-0220","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n世論を誘導するための情報（　）が行われた可能性について調査が始まった。","options":["祝賀","工作","回路","転居"],"answer":"工作","explanationKo":"문맥상 「工作」가 가장 자연스럽다. 공작; 제작; 계략라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-16','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-0230","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n自分で起こした問題なのだから、最後まで責任を持って（　）するべきだ。","options":["始末","没落","蒸留","工作"],"answer":"始末","explanationKo":"문맥상 「始末」가 가장 자연스럽다. 처리; 수습; 정리라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-16','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0242","prompt":"「ある国家や社会を構成する一般の人々を集合的にいう語。」という意味に最も近い語を選びなさい。","options":["山腹","衛生","経歴","人民"],"answer":"人民","explanationKo":"「人民」의 핵심 의미는 인민; 국민 대중이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-16','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0243","prompt":"「社会的・道徳的に正しいと考えられる道理や原則。」という意味に最も近い語を選びなさい。","options":["振り出し","区間","正義","前提"],"answer":"正義","explanationKo":"「正義」의 핵심 의미는 정의; 올바름이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-16','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0245","prompt":"「ある物事・制度・習慣・生物などが最初に生じたもとや始まり。」という意味に最も近い語を選びなさい。","options":["老衰","起源","意向","青春"],"answer":"起源","explanationKo":"「起源」의 핵심 의미는 기원; 유래이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-16','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0280","prompt":"「既存の制度・伝統・価値を守ろうとすること。また、機械・設備・システムなどを正常に保つため点検・修理すること。」という意味に最も近い語を選びなさい。","options":["保守","微塵","文語","成果"],"answer":"保守","explanationKo":"「保守」의 핵심 의미는 보수; 유지보수; 보수적 입장이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-16','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0283","prompt":"「中心となる働きや不足している部分を助け、補うこと。」という意味に最も近い語を選びなさい。","options":["協会","方式","戦術","補助"],"answer":"補助","explanationKo":"「補助」의 핵심 의미는 보조; 도움; 지원이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-16','grammar',1,'〜でなくてなんだろう','{"pattern":"〜でなくてなんだろう","meaningKo":"〜이 아니고 무엇이겠는가","explanation":"〜でなくてなんだろう는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"長年の努力が実ったのは、成功でなくてなんだろう。","ko":"문맥에서 〜이 아니고 무엇이겠는가의 의미로 쓰였다."},{"ja":"危険を承知で人を救う行為は、勇気でなくてなんだろう。","ko":"이 문장도 〜이 아니고 무엇이겠는가의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-16','grammar',2,'〜と相まって','{"pattern":"〜と相まって","meaningKo":"〜와 맞물려","explanation":"〜と相まって는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"技術の進歩が需要の増加と相まって、市場を拡大させた。","ko":"문맥에서 〜와 맞물려의 의미로 쓰였다."},{"ja":"本人の努力が周囲の支援と相まって、成果につながった。","ko":"이 문장도 〜와 맞물려의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-16','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n長年の努力が実ったのは、成功（　）。","options":["〜も同然だ","〜か否か","〜でなくてなんだろう","〜にかかわる"],"answer":"〜でなくてなんだろう","explanationKo":"문맥상 〜이 아니고 무엇이겠는가를 나타내는 「〜でなくてなんだろう」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-16','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n技術の進歩が需要の増加（　）、市場を拡大させた。","options":["〜きっての","〜と相まって","〜に忍びない","〜やら〜やら"],"answer":"〜と相まって","explanationKo":"문맥상 〜와 맞물려를 나타내는 「〜と相まって」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-16','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n事情を聞か（　）、責任の所在は分からない。","options":["〜ないことには","〜にほかならない","〜ようにも〜ない","〜こそすれ"],"answer":"〜ないことには","explanationKo":"문맥상 〜하지 않고서는를 나타내는 「〜ないことには」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-16','reading',1,'データを比較できる形にする','{"passage":"異なる時期の記録を同じ基準に整えることには、変化の方向と規模を正確に捉えられることという意義がある。しかし、定義の違いを無視すると誤った傾向が見えることにも注意しなければならない。判断の目的と前提を関係者で共有し、結果に応じて方法を見直せるようにしておく必要がある。ゆえに、数値だけでなく収集条件と定義もそろえることが重要なのである。","questions":[{"prompt":"「データを比較できる形にする」について筆者が最も重要だと考えることは何か。","options":["数値だけでなく収集条件と定義もそろえること","最初の結論を必ず維持すること","前提を関係者に知らせないこと","結果を確認せず次へ進むこと"],"answer":"数値だけでなく収集条件と定義もそろえること","explanationKo":"본문에서는 数値だけでなく収集条件と定義もそろえること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意点として挙げられているものは何か。","options":["定義の違いを無視すると誤った傾向が見えること","目的を共有すると効果が消えること","記録を残すと判断が遅れること","関係者を増やせば問題がなくなること"],"answer":"定義の違いを無視すると誤った傾向が見えること","explanationKo":"주의해야 할 점은 定義の違いを無視すると誤った傾向が見えること 가능성이다."},{"prompt":"本文の内容と合うものはどれか。","options":["変化の方向と規模を正確に捉えられること","方法は結果に関係なく固定すべきだ","判断の前提は示さない方がよい","実施後の見直しは不要である"],"answer":"変化の方向と規模を正確に捉えられること","explanationKo":"異なる時期の記録を同じ基準に整えること에는 変化の方向と規模を正確に捉えられること라는 의의가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-17','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0312","prompt":"「国連」の読み方として最も適切なものを選びなさい。","options":["あやまち","そうば","こくれん","そうどう"],"answer":"こくれん","explanationKo":"「国連」는 「こくれん」라고 읽는다. 뜻은 유엔; 국제연합이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-17','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0313","prompt":"「名称」の読み方として最も適切なものを選びなさい。","options":["しんにん","めいしょう","こころがけ","ほっさ"],"answer":"めいしょう","explanationKo":"「名称」는 「めいしょう」라고 읽는다. 뜻은 명칭; 이름이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-17','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0317","prompt":"「方式」の読み方として最も適切なものを選びなさい。","options":["ほうしき","ここ","かんよう","べんしょう"],"answer":"ほうしき","explanationKo":"「方式」는 「ほうしき」라고 읽는다. 뜻은 방식; 형식이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-17','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-0322","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n誤った情報がSNSで広がり、会社が公式に否定するほどの（　）になった。","options":["減点","改革","面会","騒動"],"answer":"騒動","explanationKo":"문맥상 「騒動」가 가장 자연스럽다. 소동; 소란; 큰 파문라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-17','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-0323","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）に応じて税負担が変わる制度について、見直しが議論されている。","options":["配慮","主導","所得","復興"],"answer":"所得","explanationKo":"문맥상 「所得」가 가장 자연스럽다. 소득; 수입라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-17','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-0327","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの料理はもともと（　）の家庭料理として広まり、後に全国で知られるようになった。","options":["理論","庶民","放置","区画"],"answer":"庶民","explanationKo":"문맥상 「庶民」가 가장 자연스럽다. 서민; 일반 대중라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-17','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-0330","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n被災地の（　）には、住宅の再建だけでなく雇用の確保も欠かせない。","options":["復興","転居","祝賀","発生"],"answer":"復興","explanationKo":"문맥상 「復興」가 가장 자연스럽다. 부흥; 복구; 재건라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-17','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-0332","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）が早く仕事に慣れるよう、先輩社員が一人ずつ指導を担当している。","options":["原書","規模","経費","新人"],"answer":"新人","explanationKo":"문맥상 「新人」가 가장 자연스럽다. 신인; 신입; 새로 들어온 사람라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-17','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-0338","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n専門性の高い保守作業は、外部の会社に（　）することになった。","options":["分裂","指令","委託","融資"],"answer":"委託","explanationKo":"문맥상 「委託」가 가장 자연스럽다. 위탁; 맡김라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-17','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-0339","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n地方へ（　）しても仕事を続けられるよう、遠隔勤務制度を利用する人が増えている。","options":["聴覚","移住","要望","危害"],"answer":"移住","explanationKo":"문맥상 「移住」가 가장 자연스럽다. 이주; 이주하여 정착함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-17','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0340","prompt":"「農作物の栽培や家畜の飼育など、農業を営むための土地・施設。」という意味に最も近い語を選びなさい。","options":["農場","青春","老衰","飽和"],"answer":"農場","explanationKo":"「農場」의 핵심 의미는 농장이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-17','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0341","prompt":"「人と直接会うこと。特に病院・施設・拘置所など、出入りが制限された場所にいる人を訪ねて会うこと。」という意味に最も近い語を選びなさい。","options":["文語","成果","庶民","面会"],"answer":"面会","explanationKo":"「面会」의 핵심 의미는 면회; 직접 만남이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-17','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0343","prompt":"「母体から子どもを産むこと。」という意味に最も近い語を選びなさい。","options":["戦術","申し分","出産","方式"],"answer":"出産","explanationKo":"「出産」의 핵심 의미는 출산; 분만이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-17','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0347","prompt":"「記事・番組・作品などを作るため、現場を訪ねたり関係者に話を聞いたりして材料を集めること。」という意味に最も近い語を選びなさい。","options":["転任","取材","善し悪し","武力"],"answer":"取材","explanationKo":"「取材」의 핵심 의미는 취재; 자료 조사이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-17','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0349","prompt":"「人や物が存在している場所。また、責任・原因などがどこにあるかという所在。」という意味に最も近い語を選びなさい。","options":["所在","対話","制服","放射能"],"answer":"所在","explanationKo":"「所在」의 핵심 의미는 소재; 있는 곳; 위치이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-17','grammar',1,'〜ないことには','{"pattern":"〜ないことには","meaningKo":"〜하지 않고서는","explanation":"〜ないことには는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"実物を見ないことには、品質を正確に判断できない。","ko":"문맥에서 〜하지 않고서는의 의미로 쓰였다."},{"ja":"事情を聞かないことには、責任の所在は分からない。","ko":"이 문장도 〜하지 않고서는의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-17','grammar',2,'〜ならまだしも','{"pattern":"〜ならまだしも","meaningKo":"〜라면 그나마 몰라도","explanation":"〜ならまだしも는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"一度ならまだしも、同じ誤りを何度も繰り返すのは問題だ。","ko":"문맥에서 〜라면 그나마 몰라도의 의미로 쓰였다."},{"ja":"子どもならまだしも、大人が規則を無視してはいけない。","ko":"이 문장도 〜라면 그나마 몰라도의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-17','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n実物を見（　）、品質を正確に判断できない。","options":["〜こそすれ","〜ないことには","〜にほかならない","〜ようにも〜ない"],"answer":"〜ないことには","explanationKo":"문맥상 〜하지 않고서는를 나타내는 「〜ないことには」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-17','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n一度（　）、同じ誤りを何度も繰り返すのは問題だ。","options":["〜ならまだしも","〜にも増して","〜をいいことに","〜ことなしに"],"answer":"〜ならまだしも","explanationKo":"문맥상 〜라면 그나마 몰라도를 나타내는 「〜ならまだしも」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-17','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n目的は責任追及（　）、再発防止にある。","options":["〜ばこそ","〜をものともせず","〜こととて","〜にあらず"],"answer":"〜にあらず","explanationKo":"문맥상 〜이 아니다를 나타내는 「〜にあらず」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-17','reading',1,'少数意見を残す','{"passage":"採用されなかった意見も記録することには、後から条件が変わった際の検討材料になることという意義がある。しかし、すべての意見を同じ重さで扱うと決定できないことにも注意しなければならない。判断の目的と前提を関係者で共有し、結果に応じて方法を見直せるようにしておく必要がある。ゆえに、不採用の理由と再検討条件を明記することが重要なのである。","questions":[{"prompt":"「少数意見を残す」について筆者が最も重要だと考えることは何か。","options":["不採用の理由と再検討条件を明記すること","最初の結論を必ず維持すること","前提を関係者に知らせないこと","結果を確認せず次へ進むこと"],"answer":"不採用の理由と再検討条件を明記すること","explanationKo":"본문에서는 不採用の理由と再検討条件を明記すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意点として挙げられているものは何か。","options":["すべての意見を同じ重さで扱うと決定できないこと","目的を共有すると効果が消えること","記録を残すと判断が遅れること","関係者を増やせば問題がなくなること"],"answer":"すべての意見を同じ重さで扱うと決定できないこと","explanationKo":"주의해야 할 점은 すべての意見を同じ重さで扱うと決定できないこと 가능성이다."},{"prompt":"本文の内容と合うものはどれか。","options":["後から条件が変わった際の検討材料になること","方法は結果に関係なく固定すべきだ","判断の前提は示さない方がよい","実施後の見直しは不要である"],"answer":"後から条件が変わった際の検討材料になること","explanationKo":"採用されなかった意見も記録すること에는 後から条件が変わった際の検討材料になること라는 의의가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-18','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0373","prompt":"「存続」の読み方として最も適切なものを選びなさい。","options":["げんしょ","きぼ","けいひ","そんぞく"],"answer":"そんぞく","explanationKo":"「存続」는 「そんぞく」라고 읽는다. 뜻은 존속; 계속 존재함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-18','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0374","prompt":"「投入」の読み方として最も適切なものを選びなさい。","options":["しゅたい","ねうち","とうにゅう","きげん"],"answer":"とうにゅう","explanationKo":"「投入」는 「とうにゅう」라고 읽는다. 뜻은 투입; 투여; 쏟아부음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-18','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0375","prompt":"「主体」の読み方として最も適切なものを選びなさい。","options":["はんげき","しゅたい","はいりょ","しゅどう"],"answer":"しゅたい","explanationKo":"「主体」는 「しゅたい」라고 읽는다. 뜻은 주체; 중심이 되는 존재이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-18','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-0376","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n創業資金を確保するため、銀行に（　）を申し込んだ。","options":["融資","墓地","密集","保温"],"answer":"融資","explanationKo":"문맥상 「融資」가 가장 자연스럽다. 융자; 대출; 자금 대여라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-18','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-0378","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n応募書類には、これまでの職務（　）を新しい順に記載してください。","options":["郷里","粗筋","株式","経歴"],"answer":"経歴","explanationKo":"문맥상 「経歴」가 가장 자연스럽다. 경력; 이력라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-18','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-0379","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n新しい法案は来週の委員会で本格的に（　）される予定だ。","options":["浮気","団結","審議","工作"],"answer":"審議","explanationKo":"문맥상 「審議」가 가장 자연스럽다. 심의; 신중한 논의라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-18','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-0380","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n旧システムから新システムへの（　）は、三か月かけて段階的に行う。","options":["慣例","移行","分裂","指令"],"answer":"移行","explanationKo":"문맥상 「移行」가 가장 자연스럽다. 이행; 전환라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-18','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-0382","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n長年の信頼関係があっても、（　）がきっかけで関係が壊れることはある。","options":["浮気","危害","聴覚","放射能"],"answer":"浮気","explanationKo":"문맥상 「浮気」가 가장 자연스럽다. 바람; 외도; 변덕스러움라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-18','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-0383","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n二十世紀の国際政治を理解するには、（　）主義と資本主義の対立を避けて通れない。","options":["老衰","飽和","交渉","共産"],"answer":"共産","explanationKo":"문맥상 「共産」가 가장 자연스럽다. 공산; 공동 소유; 공산주의 관련라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-18','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-0388","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n工事現場から古代の（　）が発見され、計画はいったん中断された。","options":["始末","浮気","遺跡","切開"],"answer":"遺跡","explanationKo":"문맥상 「遺跡」가 가장 자연스럽다. 유적; 유적지라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-18','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0392","prompt":"「機器に電気を供給する源。また、機器の電源を入れたり切ったりする機能を指すこともある。」という意味に最も近い語を選びなさい。","options":["指令","電源","融資","分裂"],"answer":"電源","explanationKo":"「電源」의 핵심 의미는 전원; 전력 공급원이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-18','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0395","prompt":"「政治家・代表者などが会い、重要な問題について公式または準公式に話し合うこと。」という意味に最も近い語を選びなさい。","options":["会談","武力","転任","着色"],"answer":"会談","explanationKo":"「会談」의 핵심 의미는 회담; 회동이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-18','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0396","prompt":"「一つの国家の主権が及ぶ土地・領域。」という意味に最も近い語を選びなさい。","options":["制服","放射能","気品","国土"],"answer":"国土","explanationKo":"「国土」의 핵심 의미는 국토이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-18','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0398","prompt":"「王・皇帝などの君主が住んだり、公的な儀式を行ったりする大規模な建物。」という意味に最も近い語を選びなさい。","options":["内閣","所在","宮殿","雅致"],"answer":"宮殿","explanationKo":"「宮殿」의 핵심 의미는 궁전이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-18','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0400","prompt":"「戦闘で目的を達成するための具体的な方法。また、競争や交渉などで使う具体的な手段にもいう。」という意味に最も近い語を選びなさい。","options":["真理","戦術","庶民","聞き取り"],"answer":"戦術","explanationKo":"「戦術」의 핵심 의미는 전술; 구체적 전략 수단이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-18','grammar',1,'〜にあらず','{"pattern":"〜にあらず","meaningKo":"〜이 아니다","explanation":"〜にあらず는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"この結果は偶然にあらず、綿密な準備の成果である。","ko":"문맥에서 〜이 아니다의 의미로 쓰였다."},{"ja":"目的は責任追及にあらず、再発防止にある。","ko":"이 문장도 〜이 아니다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-18','grammar',2,'〜にかかわる','{"pattern":"〜にかかわる","meaningKo":"〜에 관계되는 중대한","explanation":"〜にかかわる는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"安全にかかわる問題なので、直ちに報告してください。","ko":"문맥에서 〜에 관계되는 중대한의 의미로 쓰였다."},{"ja":"組織の信用にかかわる判断は慎重に行うべきだ。","ko":"이 문장도 〜에 관계되는 중대한의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-18','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nこの結果は偶然（　）、綿密な準備の成果である。","options":["〜にあらず","〜ばこそ","〜をものともせず","〜こととて"],"answer":"〜にあらず","explanationKo":"문맥상 〜이 아니다를 나타내는 「〜にあらず」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-18','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n安全（　）問題なので、直ちに報告してください。","options":["〜まみれ","〜あってこそ","〜ずじまい","〜にかかわる"],"answer":"〜にかかわる","explanationKo":"문맥상 〜에 관계되는 중대한를 나타내는 「〜にかかわる」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-18','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n努力を続けた彼に中止を告げるのは、あまり（　）。","options":["〜いかんによって","〜ずにはいられない","〜に忍びない","〜も同然だ"],"answer":"〜に忍びない","explanationKo":"문맥상 차마 〜할 수 없다를 나타내는 「〜に忍びない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-18','reading',1,'段階的に制度を導入する','{"passage":"対象を限定して新制度を試すことには、大きな損失を避けながら問題を発見できることという意義がある。しかし、試行対象が偏ると全体の効果を判断できないことにも注意しなければならない。判断の目的と前提を関係者で共有し、結果に応じて方法を見直せるようにしておく必要がある。ゆえに、本格導入前に対象の代表性を確認することが重要なのである。","questions":[{"prompt":"「段階的に制度を導入する」について筆者が最も重要だと考えることは何か。","options":["本格導入前に対象の代表性を確認すること","最初の結論を必ず維持すること","前提を関係者に知らせないこと","結果を確認せず次へ進むこと"],"answer":"本格導入前に対象の代表性を確認すること","explanationKo":"본문에서는 本格導入前に対象の代表性を確認すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意点として挙げられているものは何か。","options":["試行対象が偏ると全体の効果を判断できないこと","目的を共有すると効果が消えること","記録を残すと判断が遅れること","関係者を増やせば問題がなくなること"],"answer":"試行対象が偏ると全体の効果を判断できないこと","explanationKo":"주의해야 할 점은 試行対象が偏ると全体の効果を判断できないこと 가능성이다."},{"prompt":"本文の内容と合うものはどれか。","options":["大きな損失を避けながら問題を発見できること","方法は結果に関係なく固定すべきだ","判断の前提は示さない方がよい","実施後の見直しは不要である"],"answer":"大きな損失を避けながら問題を発見できること","explanationKo":"対象を限定して新制度を試すこと에는 大きな損失を避けながら問題を発見できること라는 의의가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-19','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0537","prompt":"「逆転」の読み方として最も適切なものを選びなさい。","options":["ぎゃくてん","やせい","ぶったい","くっせつ"],"answer":"ぎゃくてん","explanationKo":"「逆転」는 「ぎゃくてん」라고 읽는다. 뜻은 역전; 형세가 뒤바뀜이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
