INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-19','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0613","prompt":"「予感」の読み方として最も適切なものを選びなさい。","options":["ほじょ","じょうりく","よかん","はっせい"],"answer":"よかん","explanationKo":"「予感」는 「よかん」라고 읽는다. 뜻은 예감; 일이 일어날 것 같은 느낌이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-19','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-0641","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n最初の違和感を（　）だけで片づけず、データを確認して原因を探った。","options":["該当","直感","移行","団結"],"answer":"直感","explanationKo":"문맥상 「直感」가 가장 자연스럽다. 직감; 직관적으로 느낌라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-19','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-0458","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nその山は地域の人々にとって（　）な場所として長く守られてきた。","options":["神聖","敏感","幾多","乃至"],"answer":"神聖","explanationKo":"문맥상 「神聖」가 가장 자연스럽다. 신성; 성스러움라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-19','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-0473","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）のまま長時間運動すると体調を崩すことがあるので注意が必要だ。","options":["優位","早急","並びに","空腹"],"answer":"空腹","explanationKo":"문맥상 「空腹」가 가장 자연스럽다. 공복; 배고픔; 빈속라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-19','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-0483","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n対策を進めているものの、人手不足は（　）として深刻な状況だ。","options":["早急","敏感","依然","優位"],"answer":"依然","explanationKo":"문맥상 「依然」가 가장 자연스럽다. 여전히; 여전하게라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-19','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-0502","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの地域（　）の気候が、独特な農産物の生産を可能にしている。","options":["幾多","特有","無知","敏感"],"answer":"特有","explanationKo":"문맥상 「特有」가 가장 자연스럽다. 특유; 고유한 특성라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-19','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-0508","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n責任の大きさに（　）した権限を与えなければ、仕事を任せたことにはならない。","options":["相応","若しくは","優位","早急"],"answer":"相応","explanationKo":"문맥상 「相応」가 가장 자연스럽다. 상응; 걸맞음; 알맞음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-19','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-0536","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n安全上の問題が確認されたため、（　）に原因を調査して対策を取らなければならない。","options":["神聖","依然","或いは","早急"],"answer":"早急","explanationKo":"문맥상 「早急」가 가장 자연스럽다. 조속; 시급; 서둘러야 함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-19','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0540","prompt":"「必要な知識がなく、物事を知らないこと。」という意味に最も近い語を選びなさい。","options":["早急","敏感","無知","無茶"],"answer":"無知","explanationKo":"「無知」의 핵심 의미는 무지; 알지 못함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-19','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0587","prompt":"「自分のすぐ近くにあること。また、日常的に接していて親しみやすいこと。」という意味に最も近い語を選びなさい。","options":["優位","身近","日頃","若しくは"],"answer":"身近","explanationKo":"「身近」의 핵심 의미는 가까움; 친숙함; 생활 주변에 있음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-19','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0597","prompt":"「ある人・地域・物・種類などだけが本来もっている、そのもの特有の性質。」という意味に最も近い語を選びなさい。","options":["固有","無知","神聖","依然"],"answer":"固有","explanationKo":"「固有」의 핵심 의미는 고유; 그 대상만이 본래 지닌 것이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-19','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0601","prompt":"「特別な時ではない普段の日常。また、普段からという意味でも使う。」という意味に最も近い語を選びなさい。","options":["身近","空腹","碌な","日頃"],"answer":"日頃","explanationKo":"「日頃」의 핵심 의미는 평소; 평상시; 늘이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-19','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0603","prompt":"「物事の進み具合・成績・売上・体調などが順調で、よい状態にあるさま。」という意味に最も近い語を選びなさい。","options":["日頃","若しくは","好調","空腹"],"answer":"好調","explanationKo":"「好調」의 핵심 의미는 호조; 상태·성과가 좋음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-19','grammar',1,'〜に忍びない','{"pattern":"〜に忍びない","meaningKo":"차마 〜할 수 없다","explanation":"〜に忍びない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"長年使われた建物を壊すのは見るに忍びない。","ko":"문맥에서 차마 〜할 수 없다의 의미로 쓰였다."},{"ja":"努力を続けた彼に中止を告げるのは、あまりに忍びない。","ko":"이 문장도 차마 〜할 수 없다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-19','grammar',2,'〜にほかならない','{"pattern":"〜にほかならない","meaningKo":"다름 아닌 〜이다","explanation":"〜にほかならない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"今回の成果は、関係者全員の協力の結果にほかならない。","ko":"문맥에서 다름 아닌 〜이다의 의미로 쓰였다."},{"ja":"信頼を失った原因は、説明不足にほかならない。","ko":"이 문장도 다름 아닌 〜이다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-19','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n長年使われた建物を壊すのは見る（　）。","options":["〜も同然だ","〜いかんによって","〜ずにはいられない","〜に忍びない"],"answer":"〜に忍びない","explanationKo":"문맥상 차마 〜할 수 없다를 나타내는 「〜に忍びない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-19','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n今回の成果は、関係者全員の協力の結果（　）。","options":["〜かと思いきや","〜たら最後","〜にほかならない","〜やら〜やら"],"answer":"〜にほかならない","explanationKo":"문맥상 다름 아닌 〜이다를 나타내는 「〜にほかならない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-19','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n結果（　）、そこに至る過程が重要だ。","options":["〜つ〜つ","〜にも増して","〜ようにも〜ない","〜か否か"],"answer":"〜にも増して","explanationKo":"문맥상 〜보다 한층 더를 나타내는 「〜にも増して」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-19','reading',1,'説明責任の範囲','{"passage":"判断の根拠を関係者へ伝えることには、結論への理解と検証可能性を高められることという意義がある。しかし、情報を増やすだけでは要点が伝わらないことにも注意しなければならない。判断の目的と前提を関係者で共有し、結果に応じて方法を見直せるようにしておく必要がある。ゆえに、誰が何を判断するための説明かを定めることが重要なのである。","questions":[{"prompt":"「説明責任の範囲」について筆者が最も重要だと考えることは何か。","options":["誰が何を判断するための説明かを定めること","最初の結論を必ず維持すること","前提を関係者に知らせないこと","結果を確認せず次へ進むこと"],"answer":"誰が何を判断するための説明かを定めること","explanationKo":"본문에서는 誰が何を判断するための説明かを定めること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意点として挙げられているものは何か。","options":["情報を増やすだけでは要点が伝わらないこと","目的を共有すると効果が消えること","記録を残すと判断が遅れること","関係者を増やせば問題がなくなること"],"answer":"情報を増やすだけでは要点が伝わらないこと","explanationKo":"주의해야 할 점은 情報を増やすだけでは要点が伝わらないこと 가능성이다."},{"prompt":"本文の内容と合うものはどれか。","options":["結論への理解と検証可能性を高められること","方法は結果に関係なく固定すべきだ","判断の前提は示さない方がよい","実施後の見直しは不要である"],"answer":"結論への理解と検証可能性を高められること","explanationKo":"判断の根拠を関係者へ伝えること에는 結論への理解と検証可能性を高められること라는 의의가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-20','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1986","prompt":"「身なり」の読み方として最も適切なものを選びなさい。","options":["きゅうでん","みなり","かぶしき","めいしょう"],"answer":"みなり","explanationKo":"「身なり」는 「みなり」라고 읽는다. 뜻은 옷차림; 외모; 차림새이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
