INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-20','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-2284","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nその強い言葉は、不安の（　）かもしれない。","options":["裏返し","浮気","団結","該当"],"answer":"裏返し","explanationKo":"문맥상 「裏返し」가 가장 자연스럽다. 뒤집음; 뒤집힌 상태; 정반대의 표현라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-20','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-2316","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n今回は準備不足だったので、一から（　）だ。","options":["視覚","軽減","辛抱","出直し"],"answer":"出直し","explanationKo":"문맥상 「出直し」가 가장 자연스럽다. 다시 시작함; 처음부터 새로 함; 재출발라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
