INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-20','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-2536","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n氏名（　）住所を記入してください。","options":["良質","並びに","依然","重なる"],"answer":"並びに","explanationKo":"문맥상 「並びに」가 가장 자연스럽다. 및; 그리고; 아울러라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-20','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-2560","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n外出前に（　）を確認した。","options":["戸締り","出直し","発掘","略語"],"answer":"戸締り","explanationKo":"문맥상 「戸締り」가 가장 자연스럽다. 문단속; 문을 잠금라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-20','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2580","prompt":"「走って進むこと。また、物事を急いで進めること。」という意味に最も近い語を選びなさい。","options":["真理","墓地","密集","駆け足"],"answer":"駆け足","explanationKo":"「駆け足」의 핵심 의미는 구보; 달리기; 빠르게 진행함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-20','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2597","prompt":"「よく嘘をつく人。」という意味に最も近い語を選びなさい。","options":["回送","蒸留","嘘つき","転居"],"answer":"嘘つき","explanationKo":"「嘘つき」의 핵심 의미는 거짓말쟁이이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-20','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2630","prompt":"「問題・事件などを解決するための糸口となるもの。」という意味に最も近い語を選びなさい。","options":["投入","手掛かり","特派","運営"],"answer":"手掛かり","explanationKo":"「手掛かり」의 핵심 의미는 실마리; 단서; 단초이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-20','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2672","prompt":"「良いことと悪いこと。物事の長所短所や適否。」という意味に最も近い語を選びなさい。","options":["善し悪し","声明","戸締り","発掘"],"answer":"善し悪し","explanationKo":"「善し悪し」의 핵심 의미는 좋고 나쁨; 장단점; 적합 여부이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-20','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2689","prompt":"「物事に対する心の持ち方や普段からの姿勢。」という意味に最も近い語を選びなさい。","options":["結合","混同","任務","心掛け"],"answer":"心掛け","explanationKo":"「心掛け」의 핵심 의미는 마음가짐; 평소의 태도이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-20','grammar',1,'〜にも増して','{"pattern":"〜にも増して","meaningKo":"〜보다 한층 더","explanation":"〜にも増して는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"今年は昨年にも増して、慎重な対応が求められる。","ko":"문맥에서 〜보다 한층 더의 의미로 쓰였다."},{"ja":"結果にも増して、そこに至る過程が重要だ。","ko":"이 문장도 〜보다 한층 더의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-20','grammar',2,'〜ばこそ','{"pattern":"〜ばこそ","meaningKo":"바로 〜이기 때문에","explanation":"〜ばこそ는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"期待していればこそ、厳しい意見も伝えるのだ。","ko":"문맥에서 바로 〜이기 때문에의 의미로 쓰였다."},{"ja":"責任を重く考えればこそ、確認を繰り返している。","ko":"이 문장도 바로 〜이기 때문에의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-20','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n今年は昨年（　）、慎重な対応が求められる。","options":["〜か否か","〜つ〜つ","〜にも増して","〜ようにも〜ない"],"answer":"〜にも増して","explanationKo":"문맥상 〜보다 한층 더를 나타내는 「〜にも増して」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-20','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n期待していれ（　）、厳しい意見も伝えるのだ。","options":["〜でなくてなんだろう","〜ばこそ","〜をいいことに","〜きっての"],"answer":"〜ばこそ","explanationKo":"문맥상 바로 〜이기 때문에를 나타내는 「〜ばこそ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-20','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n選手たちは泥（　）になって練習を続けた。","options":["〜まみれ","〜をものともせず","〜こそすれ","〜と相まって"],"answer":"〜まみれ","explanationKo":"문맥상 온통 〜투성이를 나타내는 「〜まみれ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-20','reading',1,'予測誤差を扱う','{"passage":"予測値に含まれる不確実性を示すことには、結果の幅を踏まえて安全な判断ができることという意義がある。しかし、一つの数値だけを示すと確実な結果だと誤解されることにも注意しなければならない。判断の目的と前提を関係者で共有し、結果に応じて方法を見直せるようにしておく必要がある。ゆえに、前提と変動範囲を予測値とともに示すことが重要なのである。","questions":[{"prompt":"「予測誤差を扱う」について筆者が最も重要だと考えることは何か。","options":["前提と変動範囲を予測値とともに示すこと","最初の結論を必ず維持すること","前提を関係者に知らせないこと","結果を確認せず次へ進むこと"],"answer":"前提と変動範囲を予測値とともに示すこと","explanationKo":"본문에서는 前提と変動範囲を予測値とともに示すこと 것이 가장 중요하다고 본다."},{"prompt":"本文で注意点として挙げられているものは何か。","options":["一つの数値だけを示すと確実な結果だと誤解されること","目的を共有すると効果が消えること","記録を残すと判断が遅れること","関係者を増やせば問題がなくなること"],"answer":"一つの数値だけを示すと確実な結果だと誤解されること","explanationKo":"주의해야 할 점은 一つの数値だけを示すと確実な結果だと誤解されること 가능성이다."},{"prompt":"本文の内容と合うものはどれか。","options":["結果の幅を踏まえて安全な判断ができること","方法は結果に関係なく固定すべきだ","判断の前提は示さない方がよい","実施後の見直しは不要である"],"answer":"結果の幅を踏まえて安全な判断ができること","explanationKo":"予測値に含まれる不確実性を示すこと에는 結果の幅を踏まえて安全な判断ができること라는 의의가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-21','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0402","prompt":"「描写」の読み方として最も適切なものを選びなさい。","options":["つじつま","しよう","びょうしゃ","のうこう"],"answer":"びょうしゃ","explanationKo":"「描写」는 「びょうしゃ」라고 읽는다. 뜻은 묘사; 그려 냄이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-21','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0403","prompt":"「相場」の読み方として最も適切なものを選びなさい。","options":["いじゅう","そうば","はれつ","そうさ"],"answer":"そうば","explanationKo":"「相場」는 「そうば」라고 읽는다. 뜻은 시세; 시장 가격; 통상적인 수준이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-21','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0404","prompt":"「分裂」の読み方として最も適切なものを選びなさい。","options":["ぶんれつ","しょざい","ねばり","おうごん"],"answer":"ぶんれつ","explanationKo":"「分裂」는 「ぶんれつ」라고 읽는다. 뜻은 분열; 갈라짐이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-21','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-0407","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n窓から風が入り、静かな音楽も流れていて、とても（　）のよい空間だった。","options":["団結","該当","政策","心地"],"answer":"心地","explanationKo":"문맥상 「心地」가 가장 자연스럽다. 기분; 느낌; 감촉라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-21','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-0413","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n十分な説明なしに制度を変更したため、現場から強い（　）を受けた。","options":["辛抱","映写","反発","軽減"],"answer":"反発","explanationKo":"문맥상 「反発」가 가장 자연스럽다. 반발; 반대; 튕겨 나감라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-21','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-0414","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n為替相場の（　）が大きいため、海外取引の利益を予測しにくい。","options":["審議","変動","決行","興奮"],"answer":"変動","explanationKo":"문맥상 「変動」가 가장 자연스럽다. 변동; 변화; 오르내림라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-21','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-0420","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n夜勤が続く仕事なので、知識や経験だけでなく一定の（　）も求められる。","options":["体力","正義","業績","裏返し"],"answer":"体力","explanationKo":"문맥상 「体力」가 가장 자연스럽다. 체력; 신체적인 힘라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-21','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-0422","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n科学は絶対的な（　）を宣言するより、証拠に基づいて仮説を検証し続ける営みだ。","options":["粘り","野生","物体","真理"],"answer":"真理","explanationKo":"문맥상 「真理」가 가장 자연스럽다. 진리; 참된 이치라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-21','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-0423","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n危機を乗り越えるためには、部署の違いを超えて社員が（　）する必要がある。","options":["月賦","蔵相","団結","自信"],"answer":"団結","explanationKo":"문맥상 「団結」가 가장 자연스럽다. 단결; 단합라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-21','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-0424","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n本人の（　）を確認せずに、会社側だけで異動先を決めるべきではない。","options":["工作","意向","回送","蒸留"],"answer":"意向","explanationKo":"문맥상 「意向」가 가장 자연스럽다. 의향; 생각; 뜻라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-21','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0431","prompt":"「問題・物・状態などに必要な対応をせず、そのままにしておくこと。」という意味に最も近い語を選びなさい。","options":["放置","名称","宮殿","束の間"],"answer":"放置","explanationKo":"「放置」의 핵심 의미는 방치; 그대로 내버려 둠이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-21','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0437","prompt":"「金色に輝く金。また、比喩的に非常に価値の高いものや最も栄えた時代を表す。」という意味に最も近い語を選びなさい。","options":["戸締り","発掘","略語","黄金"],"answer":"黄金","explanationKo":"「黄金」의 핵심 의미는 황금; 금; 매우 귀중한 것이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-21','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0443","prompt":"「人に飼育・栽培されず、自然の中で生育していること。また、その動植物。」という意味に最も近い語を選びなさい。","options":["任務","起伏","野生","混同"],"answer":"野生","explanationKo":"「野生」의 핵심 의미는 야생; 자연 상태이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-21','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0446","prompt":"「一定の場所に住み、生活の拠点を置くこと。」という意味に最も近い語を選びなさい。","options":["出産","居住","窒息","発言"],"answer":"居住","explanationKo":"「居住」의 핵심 의미는 거주; 거주함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-21','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0447","prompt":"「人・車・物などを目的の方向や場所へ導くこと。また、考えや行動を一定方向へ導くこと。」という意味に最も近い語を選びなさい。","options":["誘導","委託","逆転","照明"],"answer":"誘導","explanationKo":"「誘導」의 핵심 의미는 유도; 안내하여 이끎이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-21','grammar',1,'〜まみれ','{"pattern":"〜まみれ","meaningKo":"온통 〜투성이","explanation":"〜まみれ는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"倉庫からほこりまみれの資料が見つかった。","ko":"문맥에서 온통 〜투성이의 의미로 쓰였다."},{"ja":"選手たちは泥まみれになって練習を続けた。","ko":"이 문장도 온통 〜투성이의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-21','grammar',2,'〜も同然だ','{"pattern":"〜も同然だ","meaningKo":"〜나 마찬가지다","explanation":"〜も同然だ는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"根拠を示さない説明は、何も説明しないも同然だ。","ko":"문맥에서 〜나 마찬가지다의 의미로 쓰였다."},{"ja":"準備せずに参加するのは、失敗を選ぶも同然だ。","ko":"이 문장도 〜나 마찬가지다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-21','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n倉庫からほこり（　）の資料が見つかった。","options":["〜と相まって","〜まみれ","〜をものともせず","〜こそすれ"],"answer":"〜まみれ","explanationKo":"문맥상 온통 〜투성이를 나타내는 「〜まみれ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-21','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n根拠を示さない説明は、何も説明しない（　）。","options":["〜も同然だ","〜あってこそ","〜ことなしに","〜ないことには"],"answer":"〜も同然だ","explanationKo":"문맥상 〜나 마찬가지다를 나타내는 「〜も同然だ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-21','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n（　）で、言葉が出なかった。","options":["〜いかんによって","〜こととて","〜ならまだしも","〜やら〜やら"],"answer":"〜やら〜やら","explanationKo":"문맥상 〜이며 〜이며를 나타내는 「〜やら〜やら」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-21','reading',1,'現場の裁量を設ける','{"passage":"状況に応じて担当者が方法を選べるようにすることには、例外的な事態にも速やかに対応できることという意義がある。しかし、基準がなければ担当者ごとに結果がばらつくことにも注意しなければならない。判断の目的と前提を関係者で共有し、結果に応じて方法を見直せるようにしておく必要がある。ゆえに、裁量の範囲と報告が必要な条件を定めることが重要なのである。","questions":[{"prompt":"「現場の裁量を設ける」について筆者が最も重要だと考えることは何か。","options":["裁量の範囲と報告が必要な条件を定めること","最初の結論を必ず維持すること","前提を関係者に知らせないこと","結果を確認せず次へ進むこと"],"answer":"裁量の範囲と報告が必要な条件を定めること","explanationKo":"본문에서는 裁量の範囲と報告が必要な条件を定めること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意点として挙げられているものは何か。","options":["基準がなければ担当者ごとに結果がばらつくこと","目的を共有すると効果が消えること","記録を残すと判断が遅れること","関係者を増やせば問題がなくなること"],"answer":"基準がなければ担当者ごとに結果がばらつくこと","explanationKo":"주의해야 할 점은 基準がなければ担当者ごとに結果がばらつくこと 가능성이다."},{"prompt":"本文の内容と合うものはどれか。","options":["例外的な事態にも速やかに対応できること","方法は結果に関係なく固定すべきだ","判断の前提は示さない方がよい","実施後の見直しは不要である"],"answer":"例外的な事態にも速やかに対応できること","explanationKo":"状況に応じて担当者が方法を選べるようにすること에는 例外的な事態にも速やかに対応できること라는 의의가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-22','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0462","prompt":"「調和」の読み方として最も適切なものを選びなさい。","options":["ねばり","おうごん","ひんしゅ","ちょうわ"],"answer":"ちょうわ","explanationKo":"「調和」는 「ちょうわ」라고 읽는다. 뜻은 조화; 균형 있게 어울림이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-22','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0464","prompt":"「発掘」の読み方として最も適切なものを選びなさい。","options":["せっちゅう","かんべん","はっくつ","ちゅうりつ"],"answer":"はっくつ","explanationKo":"「発掘」는 「はっくつ」라고 읽는다. 뜻은 발굴; 찾아냄이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
