INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-22','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-0470","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n全国展開の前に、三つの地域で新サービスを（　）して開始する。","options":["先行","興奮","審議","反発"],"answer":"先行","explanationKo":"문맥상 「先行」가 가장 자연스럽다. 선행; 앞서감; 먼저 실시함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-22','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-0471","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n仕事と家族の（　）を両立できるよう、短時間勤務制度を利用している。","options":["付属","先行","倍率","介護"],"answer":"介護","explanationKo":"문맥상 「介護」가 가장 자연스럽다. 개호; 간병; 돌봄라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-22','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-0474","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n工事のため、この（　）では週末の列車がすべて運休する。","options":["物体","紡績","区間","黄金"],"answer":"区間","explanationKo":"문맥상 「区間」가 가장 자연스럽다. 구간; 일정 지점 사이라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-22','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-0476","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n中央本部から避難支援を開始するよう各支部に（　）が出された。","options":["暴力","指令","月賦","蔵相"],"answer":"指令","explanationKo":"문맥상 「指令」가 가장 자연스럽다. 지령; 명령; 지시라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-22','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-0480","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n担当者が（　）のため、詳しい回答は午後になるとのことだった。","options":["不在","蒸留","工作","移行"],"answer":"不在","explanationKo":"문맥상 「不在」가 가장 자연스럽다. 부재; 자리에 없음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-22','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-0481","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n社内資料を（　）で外部へ持ち出すことは禁止されている。","options":["投入","描写","介護","無断"],"answer":"無断","explanationKo":"문맥상 「無断」가 가장 자연스럽다. 무단; 허가 없이라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-22','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-0482","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n要人の移動には複数の警備員が同行し、周囲を（　）した。","options":["激励","徐行","護衛","進路"],"answer":"護衛","explanationKo":"문맥상 「護衛」가 가장 자연스럽다. 호위; 경호; 보호라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-22','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0486","prompt":"「化学では物質の性質を保つ最小単位。数学では分数の上側の数をいう。」という意味に最も近い語を選びなさい。","options":["光熱費","分子","任務","起伏"],"answer":"分子","explanationKo":"「分子」의 핵심 의미는 분자; 분수의 위 숫자; 분자 단위이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-22','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0491","prompt":"「販売・使用に備えて倉庫や店舗などに保管されている商品・材料の数量や物そのもの。」という意味に最も近い語を選びなさい。","options":["在庫","蔵相","暴力","農場"],"answer":"在庫","explanationKo":"「在庫」의 핵심 의미는 재고; 보유 상품이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-22','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0492","prompt":"「進んでいく道筋。また、進学・就職など将来の生き方や方向。」という意味に最も近い語を選びなさい。","options":["所得","信者","心地","進路"],"answer":"進路","explanationKo":"「進路」의 핵심 의미는 진로; 앞으로 나아갈 길이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-22','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0493","prompt":"「自動車・列車・自転車などの車両が道や線路を走ること。」という意味に最も近い語を選びなさい。","options":["危機","微量","走行","行進"],"answer":"走行","explanationKo":"「走行」의 핵심 의미는 주행; 달림이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-22','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0498","prompt":"「定められた条件・分類・範囲などにちょうど当てはまること。」という意味に最も近い語を選びなさい。","options":["勢力","該当","郷里","予言"],"answer":"該当","explanationKo":"「該当」의 핵심 의미는 해당; 조건에 들어맞음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-22','grammar',1,'〜やら〜やら','{"pattern":"〜やら〜やら","meaningKo":"〜이며 〜이며","explanation":"〜やら〜やら는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"引っ越し前は手続きやら荷造りやらで忙しかった。","ko":"문맥에서 〜이며 〜이며의 의미로 쓰였다."},{"ja":"驚くやらうれしいやらで、言葉が出なかった。","ko":"이 문장도 〜이며 〜이며의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-22','grammar',2,'〜ようにも〜ない','{"pattern":"〜ようにも〜ない","meaningKo":"〜하려 해도 할 수 없다","explanation":"〜ようにも〜ない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"資料がなく、確認しようにも確認できない。","ko":"문맥에서 〜하려 해도 할 수 없다의 의미로 쓰였다."},{"ja":"連絡先が分からず、知らせようにも知らせられない。","ko":"이 문장도 〜하려 해도 할 수 없다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
