INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-22','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n資料がなく、（　）。","options":["〜かと思いきや","〜ずじまい","〜にあらず","〜ようにも〜ない"],"answer":"〜ようにも〜ない","explanationKo":"문맥상 〜하려 해도 할 수 없다를 나타내는 「〜ようにも〜ない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-22','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n相手が反論しないの（　）、要求を重ねた。","options":["〜ずにはいられない","〜にかかわる","〜をいいことに","〜か否か"],"answer":"〜をいいことに","explanationKo":"문맥상 〜을 좋은 기회로 삼아를 나타내는 「〜をいいことに」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-22','reading',1,'学習結果を振り返る','{"passage":"正誤だけでなく判断過程を確認することには、同じ種類の誤りを減らす手掛かりが得られることという意義がある。しかし、点数だけを見ると理解不足の原因が分からないことにも注意しなければならない。判断の目的と前提を関係者で共有し、結果に応じて方法を見直せるようにしておく必要がある。ゆえに、迷った理由と正解に至る根拠を記録することが重要なのである。","questions":[{"prompt":"「学習結果を振り返る」について筆者が最も重要だと考えることは何か。","options":["迷った理由と正解に至る根拠を記録すること","最初の結論を必ず維持すること","前提を関係者に知らせないこと","結果を確認せず次へ進むこと"],"answer":"迷った理由と正解に至る根拠を記録すること","explanationKo":"본문에서는 迷った理由と正解に至る根拠を記録すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意点として挙げられているものは何か。","options":["点数だけを見ると理解不足の原因が分からないこと","目的を共有すると効果が消えること","記録を残すと判断が遅れること","関係者を増やせば問題がなくなること"],"answer":"点数だけを見ると理解不足の原因が分からないこと","explanationKo":"주의해야 할 점은 点数だけを見ると理解不足の原因が分からないこと 가능성이다."},{"prompt":"本文の内容と合うものはどれか。","options":["同じ種類の誤りを減らす手掛かりが得られること","方法は結果に関係なく固定すべきだ","判断の前提は示さない方がよい","実施後の見直しは不要である"],"answer":"同じ種類の誤りを減らす手掛かりが得られること","explanationKo":"正誤だけでなく判断過程を確認すること에는 同じ種類の誤りを減らす手掛かりが得られること라는 의의가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-23','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0514","prompt":"「視覚」の読み方として最も適切なものを選びなさい。","options":["しかく","かねごと","せいりょく","こくれん"],"answer":"しかく","explanationKo":"「視覚」는 「しかく」라고 읽는다. 뜻은 시각; 보는 감각이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-23','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0519","prompt":"「回路」の読み方として最も適切なものを選びなさい。","options":["こうがく","きょうさん","うそつき","かいろ"],"answer":"かいろ","explanationKo":"「回路」는 「かいろ」라고 읽는다. 뜻은 회로; 전기 신호의 통로이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-23','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0520","prompt":"「丁目」の読み方として最も適切なものを選びなさい。","options":["ふざい","せたい","ちょうめ","うらがえし"],"answer":"ちょうめ","explanationKo":"「丁目」는 「ちょうめ」라고 읽는다. 뜻은 초메; 일본 주소의 구획 단위이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-23','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-0526","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n式典では参加者が旗を掲げ、音楽に合わせて会場内を（　）した。","options":["光熱費","行進","近眼","起伏"],"answer":"行進","explanationKo":"문맥상 「行進」가 가장 자연스럽다. 행진; 행군라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-23','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-0530","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n調査委員会には、当事者から独立した（　）的な立場が求められる。","options":["中立","進呈","発生","補助"],"answer":"中立","explanationKo":"문맥상 「中立」가 가장 자연스럽다. 중립; 어느 쪽에도 치우치지 않음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-23','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-0531","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n古い（　）の周辺を整備し、歩きやすい参道を作る工事が始まった。","options":["工作","移行","変動","墓地"],"answer":"墓地","explanationKo":"문맥상 「墓地」가 가장 자연스럽다. 묘지; 무덤이 있는 곳라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-23','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-0533","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n前半は押されていたチームが後半に（　）し、試合を引き分けに持ち込んだ。","options":["運賃","遭難","反撃","束の間"],"answer":"反撃","explanationKo":"문맥상 「反撃」가 가장 자연스럽다. 반격; 역공라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-23','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-0535","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）時代を過ごした町を二十年ぶりに訪れ、懐かしい気持ちになった。","options":["溶液","青春","略語","聴覚"],"answer":"青春","explanationKo":"문맥상 「青春」가 가장 자연스럽다. 청춘; 젊은 시절라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-23','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-0538","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n複数の写真を（　）して、実際には存在しない風景を作り出した。","options":["合成","専修","企画","従事"],"answer":"合成","explanationKo":"문맥상 「合成」가 가장 자연스럽다. 합성; 둘 이상을 합쳐 만듦라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-23','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-0541","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n病気に強く収穫量も多い新（　）の開発が各地で進められている。","options":["暴力","農場","身なり","品種"],"answer":"品種","explanationKo":"문맥상 「品種」가 가장 자연스럽다. 품종; 종류라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-23','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0548","prompt":"「一定の形や大きさをもち、空間を占めて存在する物。」という意味に最も近い語を選びなさい。","options":["心地","丁目","物体","信者"],"answer":"物体","explanationKo":"「物体」의 핵심 의미는 물체; 물리적으로 존재하는 대상이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-23','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0553","prompt":"「知識や技能を身につけさせ、特定の分野で役立つ人材を育てること。」という意味に最も近い語を選びなさい。","options":["名残","養成","危機","微量"],"answer":"養成","explanationKo":"「養成」의 핵심 의미는 양성; 교육·훈련하여 길러 냄이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-23','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0555","prompt":"「人に接するときの感じのよい態度や応対。また、人に対する好意・愛情。」という意味に最も近い語を選びなさい。","options":["愛想","徐行","遊牧","防衛"],"answer":"愛想","explanationKo":"「愛想」의 핵심 의미는 붙임성; 싹싹한 태도; 호감이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-23','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0562","prompt":"「本来区別すべき複数のものを、同じもののように取り違えたり混ぜて考えたりすること。」という意味に最も近い語を選びなさい。","options":["工学","共産","嘘つき","混同"],"answer":"混同","explanationKo":"「混同」의 핵심 의미는 혼동; 서로 다른 것을 뒤섞어 생각함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-23','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0565","prompt":"「向き合って互いに話し、考えや意見を伝え合うこと。」という意味に最も近い語を選びなさい。","options":["不在","用紙","対話","裏返し"],"answer":"対話","explanationKo":"「対話」의 핵심 의미는 대화; 서로 의견을 주고받음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-23','grammar',1,'〜をいいことに','{"pattern":"〜をいいことに","meaningKo":"〜을 좋은 기회로 삼아","explanation":"〜をいいことに는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"監督者が不在なのをいいことに、手順を省いていた。","ko":"문맥에서 〜을 좋은 기회로 삼아의 의미로 쓰였다."},{"ja":"相手が反論しないのをいいことに、要求を重ねた。","ko":"이 문장도 〜을 좋은 기회로 삼아의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-23','grammar',2,'〜をものともせず','{"pattern":"〜をものともせず","meaningKo":"〜을 아랑곳하지 않고","explanation":"〜をものともせず는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"調査隊は厳しい寒さをものともせず、作業を続けた。","ko":"문맥에서 〜을 아랑곳하지 않고의 의미로 쓰였다."},{"ja":"彼女は周囲の批判をものともせず、改革を進めた。","ko":"이 문장도 〜을 아랑곳하지 않고의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-23','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n監督者が不在なの（　）、手順を省いていた。","options":["〜か否か","〜ずにはいられない","〜にかかわる","〜をいいことに"],"answer":"〜をいいことに","explanationKo":"문맥상 〜을 좋은 기회로 삼아를 나타내는 「〜をいいことに」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-23','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n調査隊は厳しい寒さ（　）、作業を続けた。","options":["〜たら最後","〜に忍びない","〜をものともせず","〜きっての"],"answer":"〜をものともせず","explanationKo":"문맥상 〜을 아랑곳하지 않고를 나타내는 「〜をものともせず」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-23','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n十分な準備が（　）、現場で冷静に判断できる。","options":["〜にほかならない","〜あってこそ","〜こそすれ","〜つ〜つ"],"answer":"〜あってこそ","explanationKo":"문맥상 〜이 있어야만를 나타내는 「〜あってこそ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-23','reading',1,'維持費を含めて選ぶ','{"passage":"導入後に必要な費用や作業も評価することには、長期的に継続可能な案を選びやすくなることという意義がある。しかし、初期費用だけで比べると将来の負担を見落とすことにも注意しなければならない。判断の目的と前提を関係者で共有し、結果に応じて方法を見直せるようにしておく必要がある。ゆえに、導入と運用と終了にかかる負担を合わせて比べることが重要なのである。","questions":[{"prompt":"「維持費を含めて選ぶ」について筆者が最も重要だと考えることは何か。","options":["導入と運用と終了にかかる負担を合わせて比べること","最初の結論を必ず維持すること","前提を関係者に知らせないこと","結果を確認せず次へ進むこと"],"answer":"導入と運用と終了にかかる負担を合わせて比べること","explanationKo":"본문에서는 導入と運用と終了にかかる負担を合わせて比べること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意点として挙げられているものは何か。","options":["初期費用だけで比べると将来の負担を見落とすこと","目的を共有すると効果が消えること","記録を残すと判断が遅れること","関係者を増やせば問題がなくなること"],"answer":"初期費用だけで比べると将来の負担を見落とすこと","explanationKo":"주의해야 할 점은 初期費用だけで比べると将来の負担を見落とすこと 가능성이다."},{"prompt":"本文の内容と合うものはどれか。","options":["長期的に継続可能な案を選びやすくなること","方法は結果に関係なく固定すべきだ","判断の前提は示さない方がよい","実施後の見直しは不要である"],"answer":"長期的に継続可能な案を選びやすくなること","explanationKo":"導入後に必要な費用や作業も評価すること에는 長期的に継続可能な案を選びやすくなること라는 의의가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
